(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-nvfp4-dit-hybrid"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-1\">一 · 事故现场：batch 被显存卡死的 1024² 采样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-2\">二 · 它改的是数值格式与算子通路，不改采样语义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-3\">三 · 失败模式一：不回退敏感层，高噪步放大两级缩放误差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-4\">四 · 失败模式二：amax 统计没融进 attention，吃掉时延收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-5\">五 · 适用边界的量化表述</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-6\">六 · 一个可执行的判断动作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-7\">七 · 权重打包：从 per-group amax 到两级缩放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-8\">八 · 敏感度打分与回退名单的生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-9\">九 · 激活在线量化：amax 统计的插入点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-10\">十 · tcgen05 MMA 消费 NVFP4×FP8 与 epilogue 反量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-11\">十一 · latent 还原与 VAE 解码前的数值闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-12\">十二 · 端到端步骤账：每一步的显存与带宽归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-13\">十三 · 数据流上的四道关卡：从权重打包到 latent 还原</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-14\">十四 · 边界条件：回退比例、在线 amax 与解码还原的三处代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-15\">十五 · 量化关系式逐项拆解：两级缩放如何把误差压到 FP8 同级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-16\">十六 · 敏感度分数：回退比例不是拍脑袋，是可推导的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-17\">十七 · 激活在线量化：amax 统计的融合位置决定 5–10% 时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-18\">十八 · 混合精度通路的执行序：一次前向里三种精度共存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-19\">十九 · 数值漂移的收敛点：为什么 VAE 前必须还原 BF16</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-20\">二十 · 回退比例、amax 开销与 latent 还原：这套方案的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-21\">二十一 · 请求形态与批大小的耦合关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-22\">二十二 · 并发上升后暴露的带宽与算力配比问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-23\">二十三 · 敏感层回退比例对负载配方的反向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-24\">二十四 · 与采样步数、CFG 批合并叠加时的配方重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-25\">二十五 · 负载不对时的失败形态与识别信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-26\">二十六 · 配方参数的取值边界与监控闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-27\">二十七 · 硬件档位：单卡 B200 的显存账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-28\">二十八 · 并行拓扑：把 TP 留给回退层之外的场景</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-29\">二十九 · 量化方案：回退层清单是配方的主参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-30\">三十 · KV 与激活策略：latent 还原点决定画质下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-31\">三十一 · 调度参数：批大小、步数与 CFG 的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-32\">三十二 · 可复现的配置思路：从校准到定稿的四步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-33\">三十三 · 部署配方的边界：回退比例、融合质量与显存红利的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-34\">三十四 · 显存账本：权重降了，激活没降</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-35\">三十五 · 带宽与 Tensor Core 利用率的错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-36\">三十六 · 通信：分离式部署下权重与激活的两本账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-37\">三十七 · 功耗与热：峰值算力兑现后的新约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-38\">三十八 · 尾延迟与规模崩点排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-39\">三十九 · 规模上去以后，先崩的是显存账本而不是 Tensor Core</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-40\">四十 · 精度失败的三条主路径与可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-41\">四十一 · OOM 的真实来源：不是权重而是激活峰值与碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-42\">四十二 · 批抖动与路由不均：连续批处理下的量化副作用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-43\">四十三 · 尾延迟尖刺的定位：从 step 时延到 kernel 级归因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-44\">四十四 · 监控体系：三层探针与回滚触发器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-45\">四十五 · 回滚后的残余风险与校准闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-46\">四十六 · 对照轴：先分清“改数值”与“改调度”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-47\">四十七 · 与纯 FP8 路线对照：误差同级，收益在显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-48\">四十八 · 与 MX 分块路线对照：缩放粒度与回退策略的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-49\">四十九 · 与分块 PTQ 校准对照：校准是共享资产，不是重复劳动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-50\">五十 · 与调度类算法叠加：叠加顺序决定收益是否被吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-51\">五十一 · 决策表与适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-dit-hybrid-sec-52\">五十二 · 与同族算法对照时的选型边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:487px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 487.3 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"405.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">校准集跑 32–64 步前向，按 block 统计权重/激活的 per-g…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"405.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">权重按 16 元素一组打包为 NVFP4，附 FP8 per-group …</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"405.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">激活在线量化到 FP8（E4M3），首末 block 与 adaLN 调制…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"405.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理时 tcgen05 MMA 直接消费 NVFP4×FP8，累加器 FP…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"405.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">VAE 解码前把 latent 还原为 BF16，避免解码器数值漂移</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-1\">一 · 事故现场：batch 被显存卡死的 1024² 采样</h3>\n<p>先看一个线上事故的形态，而不是先看量化公式。某扩散服务把 1024² 单图采样压到单张 B200 上，SLO 以吞吐为主，团队按峰值算力估算容量：NVFP4 峰值远高于 BF16，于是把 batch 排到显存能塞下的上限。上线后出现两类症状。第一类是吞吐不达标：GPU 的 Tensor Core 利用率长期停在低位，SM 大量时间在等权重从 HBM 搬进 SMEM，而不是在算。第二类是尾延迟抖动：当调度器试图再塞一个请求进 batch 时，显存分配失败，触发回退与重排，单个请求的完成时间被拉长，SLO 窗口被打穿。根因不是算力不够，而是权重与激活仍以 BF16/FP8 存放，显存带宽成了真正的瓶颈——DiT 主干的线性层权重在每个去噪步都要被完整读一遍，步数越多，权重搬运的字节数越可观，而单张 B200 的显存容量又把 batch 死死压住。</p>\n<p>这就是本算法要解决的具体问题：DiT 主干权重与激活在 Blackwell 上仍以 BF16/FP8 存储，显存带宽与 Tensor Core 利用率受限，单张 B200 跑 1024² 采样时 batch 被显存卡死，无法吃满 NVFP4 峰值算力。注意这里的因果链是“显存容量→batch 上限→吞吐上限”，以及“权重字节数→带宽占用→MMA 空转”，两条链都指向同一个动作：把权重压到 NVFP4。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$</div>\n<p>这个式子给出的是显存账本的骨架：权重项被压到 BF16 的四分之一，激活项按 FP8 计，剩下的 scale 开销不可忽略但量级小。事故里被卡死的正是第一项——权重常驻显存决定了 batch 的天花板。把权重从 BF16 换成 NVFP4，权重显存降至 BF16 的 1/4，B200 上 1024² 采样的 batch 可提升 2–3 倍，吞吐随之抬高。这不是“算得更快”，而是“同样的显存能同时装下更多请求，且每步搬运的权重字节更少”。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-2\">二 · 它改的是数值格式与算子通路，不改采样语义</h3>\n<p>适用边界的第一条必须说清楚：这个算法只改数值格式与算子通路，不改采样步数与调度。它不碰采样器、不碰 CFG 的组织方式、不碰 batch 的调度策略，因此它可以与步数蒸馏、CFG 批合并叠加，而不是替代它们。工程上的含义是：如果你的瓶颈在采样步数太多，量化不会救你；如果你的瓶颈在 CFG 两次前向的合并方式，量化也不会救你。它只在“权重字节数与显存占用”这条链上发力。</p>\n<p>机制按数据流顺序展开：校准集跑 32–64 步前向，按 block 统计权重/激活的 per-group amax 与敏感度分数；权重按 16 元素一组打包为 NVFP4，附 FP8 per-group scale 与 FP32 二级 scale；激活在线量化到 FP8（E4M3），首末 block 与 adaLN 调制保持 BF16。推理时 tcgen05 MMA 直接消费 NVFP4×FP8，累加器 FP32，反量化在 epilogue 融合；VAE 解码前把 latent 还原为 BF16，避免解码器数值漂移。核心量化关系是两级缩放：</p>\n<div class=\"formula\">$$w_q=\\mathrm{round}_{E2M1}\\!\\left(\\frac{w}{s_1 s_2}\\right),\\quad \\hat{w}=w_q\\cdot s_1\\cdot s_2,\\quad \\hat{W}_{g}=\\mathrm{dequant}\\big(s_{g}^{\\text{outer}}\\cdot s_{g}^{\\text{inner}}\\cdot Q_{4}(W_{g})\\big)$$</div>\n<p>其中 $s_1$ 为 FP8 per-group scale、$s_2$ 为 FP32 二级 scale。16 元素一组的意义在于：E2M1 只有极少的表示点，单级缩放对组内动态范围的刻画太粗，两级缩放把 per-group 量化误差压到 FP8 同级，这是它能“压到 1/4 还不明显掉画质”的根本原因。代价是每组要额外存一个 FP8 scale 和一个 FP32 二级 scale，scale overhead 进入显存账本，但因为组大小是 16，摊到每个权重上的开销远小于权重本身。</p>\n<p>这里必须给出“不解决什么”的清单，否则读者会误用。它不解决注意力本身的带宽问题（那是异步 FA 与 FP8 注意力的主题，一句话指路即可）；不解决 VAE 解码器的吞吐（VAE 分块并行解码是另一条线）；不解决少步采样的质量（潜空间一致性少步采样是另一条线）；也不解决校准集覆盖不足导致的敏感层误判——那是分块 PTQ 校准要处理的事。它甚至不保证在所有分辨率上都划算：收益集中在显存带宽受限的大分辨率采样，1024² 下 batch 提升 2–3 倍是它的主战场，小分辨率下权重搬运占比下降，收益会被激活在线量化的额外 kernel 侵蚀。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-3\">三 · 失败模式一：不回退敏感层，高噪步放大两级缩放误差</h3>\n<p>最典型的翻车方式是把 NVFP4 一刀切到所有线性层。首末 block 与 adaLN 调制层对数值扰动极其敏感：首块接收的是带噪 latent，末块输出直接进 VAE，调制层则把时间步与条件嵌入投影成逐通道的 scale/shift。NVFP4 权重的两级缩放误差会在高噪步被放大，表现为色彩偏移与结构崩坏——不是轻微的纹理差异，而是整幅图的色调漂移与构图塌陷。工程判断是：首末 block 与调制投影必须回退到 FP8/BF16，回退比例需逐模型校准，不能照搬别的模型的配方。</p>\n<p>回退的代价直接体现在显存账本上。回退层仍以 FP8 或 BF16 存放，权重项不再是整齐的 1/4，而是“回退部分按 1/2 或 1 计、其余按 1/4 计”的加权和。敏感层回退比例随模型增大而上升，回退过多会侵蚀显存收益，batch 提升倍数从 2–3 倍往下掉。这就是规模上限的第一条约束：模型越大，敏感层占比越高，NVFP4 的净收益越薄。校准的作用就是把这个比例压到“画质可接受的最小回退集”，而不是“全回退求稳”。</p>\n<p>一个具体的工程例子：同一套 1024² 采样服务，若把 adaLN 调制投影留在 NVFP4，高噪步的输出统计量偏移会在后续 block 逐级放大，最终表现为整批图偏色；把该层回退到 FP8 后，偏移消失，而权重显存只增加很小一块。这个例子说明回退不是“保守”，而是“把有限的 FP8 预算花在敏感度分数最高的层上”。敏感度分数来自校准阶段按 block 统计的 per-group amax 与敏感度分数，32–64 步前向足以覆盖高噪到低噪的分布，步数太少会漏掉高噪段的极端激活。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-4\">四 · 失败模式二：amax 统计没融进 attention，吃掉时延收益</h3>\n<p>第二条失败模式在激活侧。激活在线量化到 FP8（E4M3）需要在每次前向时统计 amax，这引入额外 kernel。若这个 kernel 与 attention 融合不好，它会在每个 block 之间插入一次全局同步式的读写，吃掉 5–10% 的时延收益，抵消部分显存带宽红利。注意这不是“量化算错了”，而是“量化的簿记开销没被藏进已有的流水线”。在 Blackwell 上，tcgen05 MMA 的混合精度通路本身能一次前向完成 NVFP4×FP8 乘加、FP32 累加、epilogue 融合反量化，但 amax 统计发生在 MMA 之前，属于数据准备阶段，融合质量取决于它能否与前一算子（通常是 attention 的输出投影或归一化）共用一次 SMEM 驻留。</p>\n<p>工程上的判断标准很直接：把激活量化的 amax 统计与 attention 的输出处理放在同一个 kernel 里，让激活在写回 SMEM 时顺手算出组内 amax，而不是单独起一个 pass 读一遍再写一遍。若做不到，5–10% 的时延损失是实打实的，尤其在 batch 已经被抬高、SM 已经接近饱和的情况下，这部分损失会直接反映在吞吐上。这也是“规模上限受 kernel 融合质量约束”的具体含义：同样的权重配方，融合做得好与不好，端到端收益可以差出一个档位。</p>\n<p>第三个失败点在 VAE 侧，容易被忽略。VAE 解码前必须把 latent 还原为 BF16，否则解码器数值漂移会导致细节糊化，量化收益被画质退化抵消。扩散主干省下来的显存与带宽，如果在解码阶段被数值问题吃掉画质，整条链路的性价比就不成立。这条约束也划出了算法的边界：它管到 latent 为止，VAE 解码器的数值路径不在它的作用域内，需要与 VAE 分块并行解码那条线配合。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-5\">五 · 适用边界的量化表述</h3>\n<p>把边界写成可核对的判据，比写成定性描述更有用。第一条判据是瓶颈位置：用权重字节数乘以每步读取次数，与激活字节数、attention 的 KV 读写做对比，若权重搬运占 HBM 流量的主导，这个算法划算；若 attention 的 KV 读写占主导，收益会被稀释。第二条判据是分辨率：1024² 下 batch 提升 2–3 倍是给定事实，分辨率下降时权重占比下降，收益递减。第三条判据是回退比例：敏感层回退比例随模型增大而上升，回退过多会侵蚀显存收益，当回退集大到让权重项接近 FP8 的水平时，这个算法相对纯 FP8 量化的优势只剩两级缩放的精度红利（FID 退化通常 <0.5），显存红利已经消失。</p>\n<table class=\"mini\"><thead><tr><th>边界维度</th><th>划算区间</th><th>不划算或失效区间</th></tr></thead><tbody><tr><td>瓶颈类型</td><td>权重搬运主导 HBM 流量</td><td>attention KV 读写主导</td></tr><tr><td>分辨率</td><td>1024² 大分辨率采样</td><td>小分辨率，权重占比低</td></tr><tr><td>模型规模</td><td>敏感层回退比例可控</td><td>回退过多，权重项逼近 FP8</td></tr><tr><td>kernel 融合</td><td>amax 统计融入 attention 输出</td><td>独立 pass，损失 5–10% 时延</td></tr><tr><td>下游数值</td><td>latent 还原 BF16 后进 VAE</td><td>直接以量化 latent 解码</td></tr></tbody></table>\n<p>第四条判据是校准集覆盖度：32–64 步前向、按 block 统计 per-group amax 与敏感度分数，这套流程的可靠性取决于校准集是否覆盖了实际请求的 prompt 分布与分辨率。覆盖不足时，敏感度分数会把不该回退的层标成敏感层，或把该回退的层漏掉，前者侵蚀显存收益，后者直接导致第三节描述的色彩偏移与结构崩坏。规模上限因此受校准集覆盖度与 kernel 融合质量双重约束，而不是受 NVFP4 格式本身约束。</p>\n<p>最后一条判据是叠加关系。因为它只改数值格式与算子通路，所以它与步数蒸馏、CFG 批合并是正交的：步数蒸馏减少每请求的权重读取次数，CFG 批合并改变 batch 的组织方式，两者都会改变“权重搬运占总流量的比例”，从而改变这个算法的边际收益。工程上应先固定采样与调度侧的优化，再在这个算法的配方上做敏感层回退比例的校准——顺序反了，校准出来的回退集会对应一个不存在的流量结构。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-6\">六 · 一个可执行的判断动作</h3>\n<p>落到具体动作：在目标模型上先用 32–64 步前向跑校准，得到每层的 per-group amax 与敏感度分数；把权重按 16 元素一组打包为 NVFP4，附 FP8 per-group scale 与 FP32 二级 scale；按敏感度分数从高到低把首末 block 与 adaLN 调制投影放进 FP8 回退集，直到画质指标（FID 退化 <0.5）与显存账本同时满足；激活在线量化到 FP8（E4M3），并把 amax 统计与 attention 输出处理融合到同一个 kernel，用端到端时延验证 5–10% 的损失是否被消掉；VAE 解码前确认 latent 已还原为 BF16。任何一步不满足，就先回到边界判据表核对瓶颈位置，而不是继续调量化参数——因为这个算法的失效模式大多不在量化精度本身，而在它被用在了不满足适用边界的地方。</p>\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-7\">七 · 权重打包：从 per-group amax 到两级缩放</h3>\n<p>校准阶段的第一步不是量化，而是把每个线性层的权重按 16 元素一组切开，逐组统计 amax。这一步的输入是 BF16 权重张量，输出是两组标量：FP8 per-group scale $s_1$ 与 FP32 二级 scale $s_2$。分组粒度选 16 而非 32 或 128，是因为 NVFP4 的 E2M1 只有 4 个尾数位，组内动态范围必须压得足够窄，两级缩放才有意义——$s_1$ 吃掉组内大部分动态范围，$s_2$ 再把 $s_1$ 自身的 FP8 表示误差补回来。</p>\n<div class=\"formula\">$$w_q=\\mathrm{round}_{E2M1}\\!\\left(\\frac{w}{s_1 s_2}\\right),\\quad \\hat{w}=w_q\\cdot s_1\\cdot s_2$$</div>\n<p>打包后的存储形态是：每 16 个权重共享 1 字节的 FP8 scale 加 1 个 FP32 二级 scale，权重本体每元素 4 bit。折算下来权重显存约为 BF16 的 1/4，但 scale overhead 不是零——每 16 元素多出 5 字节，等价于每元素额外 2.5 bit，实际压缩比略低于名义 4 倍。这个 overhead 在估算 $\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$ 时必须计入，否则 batch 规划会偏乐观。代价侧：打包本身是一次离线 pass，不进入推理热路径；但分组越细，scale 张量的读取带宽越高，epilogue 反量化时要按组广播 $s_1 s_2$，这是后续 MMA 融合要背的账。</p>\n<p>具体例子：一个 1024² 采样的 DiT 主干，单个 attention 投影层权重若为 BF16 的若干 MB 量级，按 16 元素分组后 scale 张量本身占权重字节数的约 1/16 再加 FP32 尾巴，这部分在 L2 里驻留与否直接决定反量化是走寄存器还是走显存。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-8\">八 · 敏感度打分与回退名单的生成</h3>\n<p>校准集跑 32–64 步前向，同时做两件事：统计 per-group amax，以及对每个 block 计算敏感度分数。敏感度分数的输入是该 block 输出在量化前后的偏差范数（相对 BF16 参考），输出是一个标量排序，用来决定哪些层进 NVFP4、哪些回退 FP8、哪些保持 BF16。首末 block 与 adaLN 调制投影几乎必然落在回退名单里——首 block 承接 latent 输入，末 block 直接决定输出像素分布，调制投影的 scale/shift 一旦量化误差放大会整体改变条件注入的增益。</p>\n<ul>\n<li>输入：校准 prompt/latent 对、32–64 步去噪轨迹上的中间激活。</li>\n<li>输出：每层一个量化档位标签（NVFP4 / FP8 / BF16）与回退比例。</li>\n<li>代价：校准本身是离线的一次性开销，但回退比例是推理期的持续成本——回退层越多，权重显存越接近 FP8 而非 1/4 BF16，batch 提升从 2–3 倍向下滑。</li>\n</ul>\n<p>这里的工程判断是：敏感度分数不能只看单层重建误差，要看该层误差在去噪轨迹高噪步上的传播。高噪步的激活动态范围最大，两级缩放的组内误差会被放大成色彩偏移。因此校准集必须覆盖不同噪声水平的步，32–64 步的采样刚好给出足够多的噪声档位采样点。回退比例逐模型校准，模型越大，attention 与 FFN 的深度堆叠越多，误差累积越明显，回退名单往往越长。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-9\">九 · 激活在线量化：amax 统计的插入点</h3>\n<p>推理时激活不预量化，而是每个 linear 前在线统计 amax 再量化到 FP8（E4M3）。输入是 BF16 激活张量，输出是 FP8 激活加一个 per-tensor 或 per-group 的 scale。这一步的代价最容易被低估：amax 归约是一个独立的 reduction kernel，它读一遍激活、写一个标量，然后量化 kernel 再读一遍激活。若这两个 kernel 不能和上游的 attention 输出或残差加法融合，就在热路径上插入两次额外访存。</p>\n<p>失败模式很直接：amax 统计若未与 attention 融合，会吃掉 5–10% 的时延收益。在 1024² 采样、batch 被显存卡死的场景下，这部分时延损失换来的显存收益仍然为正，但如果 kernel 融合质量差到让 SM 占用率下降，收益会被抵消。工程上的做法是把 amax 归约折进上游 epilogue——attention 输出写回时顺手做局部 max，量化 kernel 只做一次读改写。</p>\n<p>首末 block 与 adaLN 调制保持 BF16，意味着这些层的激活不做在线量化，直接以 BF16 进 MMA 的混合精度通路。这减少了这些层的 kernel 数量，但也让它们的激活显存回到 BF16 水平——在激活显存占比不高的 DiT 里可以接受，因为主干成本在权重。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-10\">十 · tcgen05 MMA 消费 NVFP4×FP8 与 epilogue 反量化</h3>\n<p>这是整条链路唯一真正吃满 Blackwell 算力的步骤。输入是打包好的 NVFP4 权重块与 FP8 激活块，输出是 FP32 累加结果。tcgen05 MMA 的混合精度通路允许 A 操作数为 NVFP4、B 操作数为 FP8，累加器驻留 TMEM 且为 FP32——这一点关键：两级缩放的乘积 $s_1 s_2$ 不参与 MMA 内部累加，而是在 epilogue 里乘回去，避免在 Tensor Core 内部引入额外舍入。</p>\n<ul>\n<li>机制：MMA 指令直接消费 4 bit 权重与 8 bit 激活，K 维按 16 元素组对齐，组边界与 scale 边界重合。</li>\n<li>代价：TMEM 容量决定单次 MMA 的 N 维上限，累加器 FP32 使 TMEM 占用翻倍于 FP16 累加，这限制了同时驻留的 tile 数，进而影响 2-SM MMA 的配对策略。</li>\n<li>代价：epilogue 反量化要按组广播 scale，若 scale 张量未与权重块同布局，会产生非合并访存。</li>\n</ul>\n<p>具体例子：一个 FFN 的 up-projection，K 维若为数千量级，按 16 元素分组就是数百个 scale；epilogue 每写一个输出 tile 要读对应组的 $s_1 s_2$，这些 scale 应提前搬到 shared memory 或寄存器，否则反量化带宽会盖过 MMA 节省下来的权重带宽。这也是为什么分组粒度不能无限细——16 是精度与 epilogue 开销的折中点。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-11\">十一 · latent 还原与 VAE 解码前的数值闸门</h3>\n<p>DiT 主干输出的是 latent，进 VAE 解码器之前必须把 latent 从量化通路的数值域还原为 BF16。输入是 FP32 累加后经 epilogue 反量化、再经输出投影得到的 latent，输出是 BF16 latent 张量。这一步不是格式转换那么简单：VAE 解码器对输入分布的微小漂移极其敏感，NVFP4 两级缩放误差若残留在 latent 里，解码器会把高频细节糊化，量化带来的吞吐收益被画质退化抵消。</p>\n<p>代价侧：还原操作本身是一次 elementwise cast，带宽开销与 latent 尺寸成正比，相对主干可忽略；但它是一道硬闸门，不能省。工程上把它放在 DiT 最后一个 block 的输出之后、VAE 分块并行解码之前，确保解码器的每个分块拿到的都是 BF16 输入。若模型在 latent 上还做了 scaling/shift 的后处理，这些操作应在 BF16 域完成，而不是在反量化后的 FP32 域里夹着做。</p>\n<p>失败模式：VAE 解码前未还原 BF16 时，解码器数值漂移导致细节糊化。这条与首末 block 未回退导致的色彩偏移是两类不同的退化——前者是高频细节损失，后者是低频色偏，校准时要分开看指标。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-12\">十二 · 端到端步骤账：每一步的显存与带宽归属</h3>\n<p>把五步按数据流串起来，可以得到一张代价归属表。权重打包与敏感度打分是离线的一次性成本，不进入 SLO；推理热路径上的持续成本集中在三处：激活 amax 归约的额外访存、epilogue 反量化的 scale 广播、以及回退层带来的显存回吐。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入 → 输出</th><th>热路径代价</th></tr></thead><tbody>\n<tr><td>权重打包</td><td>BF16 权重 → NVFP4 + $s_1$ + $s_2$</td><td>离线；scale overhead 摊入显存</td></tr>\n<tr><td>敏感度打分</td><td>校准激活 → 档位标签</td><td>离线；决定回退比例</td></tr>\n<tr><td>激活在线量化</td><td>BF16 激活 → FP8 + scale</td><td>额外 reduction kernel，未融合吃 5–10% 时延</td></tr>\n<tr><td>tcgen05 MMA</td><td>NVFP4×FP8 → FP32 累加</td><td>TMEM 容量约束 tile 并行度</td></tr>\n<tr><td>epilogue 反量化</td><td>FP32 → BF16 输出</td><td>scale 广播的访存带宽</td></tr>\n<tr><td>latent 还原</td><td>量化域 latent → BF16</td><td>elementwise cast，画质闸门</td></tr>\n</tbody></table>\n<p>显存账的核心是权重从 BF16 降到 1/4 后，batch 在 B200 上可提升 2–3 倍，这直接抬高吞吐；但回退层按 FP8 存储，实际权重显存介于 1/4 与 1/2 BF16 之间，batch 提升幅度取决于回退比例。带宽账的核心是 MMA 读权重的字节数降到 1/4，权重带宽不再是大分辨率采样的瓶颈，瓶颈转移到激活 amax 与 epilogue scale 这两处新增访存。工程判断：先测回退比例，再测 amax kernel 的融合度，两者共同决定这套混合精度配方在具体模型上是否真的把 batch 推上去——只改数值格式不改调度，收益上限由这两项决定。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-13\">十三 · 数据流上的四道关卡：从权重打包到 latent 还原</h3>\n<p>按一次前向的数据流拆开看，这套方案在推理路径上要过四道关卡，每一道都有明确的输入、输出与代价。第一关是权重驻留：线性层权重按 16 元素一组打包为 NVFP4，每组附一个 FP8 per-group scale（$s_1$）与一个 FP32 二级 scale（$s_2$），反量化关系为 $\\hat{W}_{g}=\\mathrm{dequant}(s_{g}^{\\text{outer}}\\cdot s_{g}^{\\text{inner}}\\cdot Q_{4}(W_{g}))$。输入是校准阶段冻结的量化权重与两级 scale，输出是常驻显存的打包张量，代价体现在显存账本上：$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$。注意 scale overhead 不是零头——16 元素一组意味着每 16 个 4 bit 值（8 字节）配一个 FP8 scale（1 字节）加一个 FP32 二级 scale（4 字节），开销比例约 5/8，即打包后实际占用约为纯 4 bit 的 1.6 倍。这正是“权重降至 1/4”这一说法在工程上要打折的地方，也是敏感层回退比例上升后显存收益被侵蚀的直接原因。</p>\n<p>第二关是激活在线量化。输入是上一层输出的 BF16/FP8 激活，输出是 E4M3 格式的激活张量与当步 amax 统计。这里的关键代价是 amax 统计本身要读一遍激活、写一个归约结果，若不能与 attention 或前一个算子的 epilogue 融合，就会插入独立 kernel 并吃掉 5–10% 的时延收益——在 1024² 单图采样这种以吞吐为 SLO 的负载上，这部分损失直接抵消显存带宽红利。第三关是 MMA 消费：tcgen05 MMA 直接吃 NVFP4×FP8，累加器保持 FP32，反量化在 epilogue 融合完成。这一步的输入是打包权重与量化激活，输出是 FP32 部分和，代价从显存带宽转移到 Tensor Core 通路——混合精度通路让一次前向同时完成低精度乘与高精度累加，避免了“先反量化到 BF16 再乘”的中间张量落地，这是收益的真正来源。第四关是出口还原：VAE 解码前必须把 latent 还原为 BF16，输入是 FP32 累加得到的 latent，输出是 BF16 latent。若省掉这一步，解码器数值漂移会让细节糊化，量化省下的显存与带宽被画质退化抵消，属于典型的“省在主干、赔在出口”。</p>\n<p>边界与失效条件集中在两处。其一是敏感层回退比例：首末 block 与 adaLN 调制投影必须走 FP8/BF16 回退，否则两级缩放误差会在高噪步被放大，表现为色彩偏移与结构崩坏；而回退比例随模型增大而上升，回退过多会直接侵蚀 1/4 权重显存带来的 batch 提升（2–3 倍）。其二是校准集覆盖度：32–64 步前向统计出的 per-group amax 与敏感度分数决定了哪些层能安全走 NVFP4，覆盖不足时敏感度分数失真，回退决策就退化为拍脑袋。规模上限因此不由硬件决定，而由校准集覆盖度与 kernel 融合质量共同约束。</p>\n<table class=\"mini\"><thead><tr><th>关卡</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>权重驻留</td><td>NVFP4 打包权重 + FP8/FP32 两级 scale</td><td>常驻显存张量</td><td>scale overhead 约使实际占用达纯 4 bit 的 1.6 倍</td></tr><tr><td>激活在线量化</td><td>BF16/FP8 激活</td><td>E4M3 激活 + amax</td><td>未融合时吃掉 5–10% 时延收益</td></tr><tr><td>MMA 消费</td><td>NVFP4 权重 × FP8 激活</td><td>FP32 部分和</td><td>依赖 tcgen05 混合精度通路，epilogue 融合反量化</td></tr><tr><td>出口还原</td><td>FP32 latent</td><td>BF16 latent</td><td>缺失则解码器漂移、细节糊化</td></tr></tbody></table>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-14\">十四 · 边界条件：回退比例、在线 amax 与解码还原的三处代价</h3>\n<p>这套混合精度通路的收益不是无条件成立的，它的边界由三处代价共同划定。第一处是敏感层回退：首末 block 与 adaLN 调制投影必须走 FP8/BF16，否则 NVFP4 两级缩放的残差会在高噪步被放大——早期扩散步的激活动态范围最宽，per-group amax 被少数离群通道主导，$s_1 s_2$ 的乘积把整组量化步长抬高，E2M1 的 4 位尾数在低幅值元素上几乎退化为符号位，误差经残差链路累积后表现为色彩偏移与结构崩坏。回退比例不是常数，随模型深度与调制方式上升，回退过多则权重显存重新向 $\\frac{1}{4}W_{\\text{BF16}}$ 之上回涨，直接侵蚀 batch 提升的 2–3 倍空间。</p>\n<p>第二处代价在激活侧。在线量化到 E4M3 需要每个 token 组的 amax 归约，若该归约未与 attention 的 softmax 或 QKV 投影融合，就会额外插入一个独立 kernel，其启动与访存开销吃掉 5–10% 的时延收益——这部分损失与权重压缩带来的带宽红利方向相反，在 batch 已经较大、计算而非带宽成为瓶颈时尤为明显。工程判断是：只有当 amax 归约被吸收进前一个算子的 epilogue、与 tcgen05 MMA 的流水重叠时，激活量化的净收益才为正；否则应把激活留在 BF16，仅保留权重的 NVFP4 压缩。</p>\n<p>第三处是输出端的数值还原。VAE 解码器对 latent 的幅值分布敏感，若直接把量化通路产生的低精度 latent 送入解码器，解码器内部的归一化与卷积会把量化噪声放大为细节糊化，画质退化抵消掉 FID &lt;0.5 的收益。因此必须在解码前显式还原为 BF16，这一步是纯带宽开销：一次 latent 的张量读写，尺寸随分辨率平方增长，1024² 下不可忽略，但它换来的是解码器数值稳定，属于不可省略的固定成本。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>敏感层回退</td><td>首末 block/调制层未回退</td><td>显存收益被回退比例侵蚀</td></tr><tr><td>激活在线量化</td><td>amax 归约未融合</td><td>5–10% 时延收益损失</td></tr><tr><td>latent 还原</td><td>未还原为 BF16</td><td>解码细节糊化、画质退化</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-15\">十五 · 量化关系式逐项拆解：两级缩放如何把误差压到 FP8 同级</h3>\n<p>核心关系式只有两行，但每一项都对应一个必须落到 kernel 里的决定：</p>\n<div class=\"formula\">$$w_q=\\mathrm{round}_{E2M1}\\!\\left(\\frac{w}{s_1 s_2}\\right),\\quad \\hat{w}=w_q\\cdot s_1\\cdot s_2$$</div>\n<p>先看 $w_q$：它是以 16 个权重元素为一组的 E2M1 码字，每个元素只占 4 bit，可表示集合为 $\\{0,\\pm0.5,\\pm1,\\pm1.5,\\pm2,\\pm3,\\pm4,\\pm6\\}$——注意这个集合在 1 附近最密、向两端稀疏，这正是 DiT 权重近似高斯分布时想要的形状。再看 $s_1$：它是该组 16 个元素共享的 FP8（E4M3）per-group scale，把组内最大值映射进 E2M1 的满量程 6.0；$s_2$ 是跨若干组共享的 FP32 二级 scale，用来吸收 $s_1$ 自身在 FP8 表示下的动态范围不足。反量化 $\\hat{w}=w_q\\cdot s_1\\cdot s_2$ 在数学上是两次乘法，但在硬件上不是：tcgen05 MMA 消费的是 $w_q$ 与激活的 FP8 码字，$s_1 s_2$ 的乘积被折叠进 epilogue 的逐通道缩放，累加器保持 FP32。</p>\n<p>推导的关键一步在于误差界的收紧。若只有单级缩放，组内量化误差上界约为 $\\Delta_{\\text{single}}=\\frac{\\max_g|w|}{2^{k-1}}$，其中 $k$ 为码字有效位数；引入两级后，有效步长变为 $s_1 s_2$ 所定义的格点间距，而 $s_2$ 的 FP32 精度使得 $s_1$ 的表示误差不再直接乘进权重——换言之，误差被拆成“组内舍入”与“缩放表示”两部分，后者被 FP32 二级 scale 压到可忽略。这就是“per-group 量化误差压到 FP8 同级”的来源：4 bit 码字本身粗糙，但 16 元素一组的粒度加上两级缩放，让每个元素的相对误差与 E4M3 的 3 位尾数在同一量级。代价是每组要存一个 FP8 scale（16 元素摊 8 bit，即每权重额外 0.5 bit）加一个 FP32 二级 scale（摊到更大分组上），这就是公式里 $\\text{scale overhead}$ 那一项的来源。</p>\n<p>把三项代进显存估算：</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$</div>\n<p>权重项从 1 降到 1/4，激活项从 1 降到 1/8（相对 BF16 激活），而 scale overhead 是唯一随分组粒度上升的项。工程判断很直接：分组越细，画质越好、overhead 越大；16 元素一组是在 E2M1 码字粒度与 scale 带宽之间取的折中，再细下去 scale 读取会开始吃掉权重带宽节省下来的那部分收益。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-16\">十六 · 敏感度分数：回退比例不是拍脑袋，是可推导的判据</h3>\n<p>校准阶段跑 32–64 步前向，对每个 block 同时统计两个量：per-group amax（决定 $s_1$）与敏感度分数。敏感度分数的可实现定义是“该 block 输出对量化扰动的二阶响应”，即用校准激活 $x$ 与量化前后权重差 $\\delta W=\\hat{W}-W$ 构造</p>\n<div class=\"formula\">$$\\text{score}_b=\\mathbb{E}\\left[\\frac{\\|\\,\\delta W_b\\,x_b\\,\\|_2}{\\|W_b x_b\\|_2}\\right]$$</div>\n<p>这个比值直接给出“相对输出扰动”，比看权重本身的量化误差更有意义，因为 DiT 的残差流会把局部扰动按层放大或衰减。首末 block 的分数天然偏高：首 block 承接 latent 输入，末 block 直接决定输出投影，两者的 $\\|W_b x_b\\|$ 分母小、扰动传播路径短，任何色彩偏移都会原样进入 VAE 解码。adaLN 调制投影的分数也高，因为它生成的是逐通道的 scale/shift，误差会被乘到整条残差流上，属于全局增益型扰动而非局部噪声。</p>\n<p>于是回退策略可以写成可执行判据：按 score 排序，超过阈值的层走 FP8（首末 block 与调制投影甚至可以保持 BF16），其余走 NVFP4×FP8。伪代码思路如下：</p>\n<ul>\n<li>对每个线性层 $l$：收集 32–64 步校准前向的输入激活，按 16 元素组统计 $\\max|x|$ 与 $\\max|w|$，得 $s_1^{w}, s_1^{x}$；</li>\n<li>用上式算 $\\text{score}_l$，与阈值 $\\tau$ 比较，标记 $\\text{precision}_l\\in\\{\\text{NVFP4},\\text{FP8},\\text{BF16}\\}$；</li>\n<li>把 $\\text{precision}_l$、$s_1^{w}$、$s_2$ 打包进权重描述符，供推理时按层分派 MMA 通路；</li>\n<li>若回退层占比超过预算（例如权重显存收益被侵蚀到不可接受），回头收紧 $\\tau$ 并重跑校准，而不是逐层手工挑。</li>\n</ul>\n<p>系统代价在这里体现为校准成本与收益的耦合：回退比例随模型增大而上升，回退过多会侵蚀那 1/4 的权重显存收益，而 batch 提升 2–3 倍的前提正是权重显存真的降下来了。所以 $\\tau$ 不是画质参数，是容量参数——它同时决定 FID 退化（&lt;0.5 的目标）和单张 B200 上 1024² 采样能塞进多少 batch。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-17\">十七 · 激活在线量化：amax 统计的融合位置决定 5–10% 时延</h3>\n<p>权重是离线量化的，激活必须在线量化到 FP8（E4M3）。最朴素的实现是每个线性层前插一个 reduce-max kernel 求 amax、再插一个量化 kernel，两趟额外读写把激活带宽翻倍。在带宽受限的大分辨率采样里，这正好抵消掉权重降位带来的红利，实测口径是吃掉 5–10% 时延收益。</p>\n<p>可实现的融合思路是把 amax 统计塞进上游算子的 epilogue：attention 输出或上一层的 GEMM epilogue 在写回 FP16/BF16 激活的同时，用 warp 内 shuffle 归约出块内 amax，写进一个小的 per-tensor 或 per-group scale 缓冲；紧随其后的量化 kernel 只读这个缓冲，不再重扫激活。伪代码：</p>\n<ul>\n<li>上游 epilogue：每个 warp 处理 16 元素组，`amax = max(|x_i|)`，`s1 = amax / 6.0`（E4M3 满量程按实现取），`q = round_E4M3(x / s1)`；</li>\n<li>把 `q` 与 `s1` 一并写入激活缓冲，下游 MMA 直接以 `q` 为 A 操作数；</li>\n<li>若上游是 attention 且已融合 softmax epilogue，则 amax 归约与 softmax 的 max 归约可共享同一次 warp reduce，边际成本接近零。</li>\n</ul>\n<p>代价分析要落到具体数字上：融合得好，额外 kernel 消失，激活路径只剩一次写一次读，5–10% 的时延损失被收回；融合不好（比如 attention 的 epilogue 已被占满、寄存器压力顶到上限），就只能退回独立 kernel，此时应把量化粒度放粗（per-tensor 而非 per-group）以减少 scale 读写，用画质换时延。这是一个明确的工程取舍点，而不是可以两头都要的优化。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-18\">十八 · 混合精度通路的执行序：一次前向里三种精度共存</h3>\n<p>推理时的关键约束是“一次前向完成”，不能因为精度切换而把前向拆成多趟。tcgen05 MMA 的混合精度通路允许 A 操作数为 NVFP4、B 操作数为 FP8，累加器 FP32，因此权重侧 NVFP4 与激活侧 FP8 可以在同一条 MMA 指令里相乘，反量化折叠进 epilogue。执行序按数据流是：</p>\n<ul>\n<li>线性层主体：$W$ 以 NVFP4 码字 + $s_1^{w}$（FP8）+ $s_2$（FP32）驻留显存，$x$ 以 FP8 码字 + $s_1^{x}$ 驻留；MMA 输出 FP32 部分和；epilogue 乘上 $s_1^{w}s_2 s_1^{x}$ 得 BF16/FP16 结果。</li>\n<li>首末 block 与 adaLN 调制：走 FP8 回退通路，权重与激活同为 E4M3，累加器仍 FP32；调制投影可进一步保持 BF16，因为它的输出要广播到整条残差流。</li>\n<li>VAE 解码前：latent 从 FP8/BF16 混合态还原为 BF16 再进解码器。</li>\n</ul>\n<p>这里有一个容易被忽略的推导点：epilogue 里的缩放因子是三个量的乘积，若把它们分别乘进部分和，会引入三次舍入；正确做法是先在 FP32 里算出 $s=s_1^{w}s_2 s_1^{x}$（一次乘法），再对部分和做一次乘。这样反量化的舍入误差只出现一次，与“两级缩放把误差压到 FP8 同级”的结论一致。代价是 epilogue 需要一个额外的 FP32 标量乘与一次类型转换，相对 MMA 主循环可忽略，但它决定了画质能否守住 FID 退化 &lt;0.5 的目标。</p>\n<p>显存侧的账要算清：权重 1/4、激活 1/8，加上每 16 元素一个 FP8 scale 与更大分组上的 FP32 二级 scale，总占用仍显著低于 BF16 基线，这正是 1024² 采样 batch 能提升 2–3 倍的物理基础。带宽侧则是另一回事：权重读取量降到 1/4 后，瓶颈从权重带宽转向激活带宽与 scale 读取，因此 scale 的布局（是否与码字交错存放、是否走同一 cacheline）会直接影响实际达成的带宽节省比例。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-19\">十九 · 数值漂移的收敛点：为什么 VAE 前必须还原 BF16</h3>\n<p>DiT 主干对量化误差有一定容忍度，因为残差流与 LayerNorm 会反复重整数值尺度；VAE 解码器不具备这种重整能力。解码器的上采样卷积与 attention 对输入的微小偏移高度敏感，latent 里 4 bit 码字带来的高频扰动会在解码阶段被放大成细节糊化。这就是失败模式里“VAE 解码前未把 latent 还原为 BF16，细节糊化抵消量化收益”的机制解释：不是误差变大，而是误差进入了没有归一化保护的子系统。</p>\n<p>可实现的处理是在 DiT 最后一个 block 的 epilogue 里做一次显式的 BF16 还原：把 FP32 累加结果按 BF16 舍入写出，而不是让 FP8 码字直接流进解码器。这一步的代价是一次类型转换与一次写回，量级远小于解码本身；收益是把量化误差挡在解码器之外，使画质退化停留在主干侧的可控范围内。与之配套的是首末 block 的回退——首 block 决定输入 latent 的编码方式，末 block 决定输出 latent 的还原方式，两端都守住，中间的 NVFP4 才有意义。</p>\n<p>把这条与回退判据合起来看，整套方案的稳定性其实由三个收敛点共同保证：首 block 的 FP8/BF16 回退挡住输入侧扰动，adaLN 调制的回退挡住全局增益型误差，VAE 前的 BF16 还原挡住解码侧放大。任何一个点失守，画质退化就不再是 &lt;0.5 的量级，而是肉眼可见的色彩偏移与结构崩坏。因此校准阶段除了算 score，还应把这三个点作为硬约束固定下来，不参与阈值调优——它们不是可交易的显存，而是方案成立的前提。</p>\n<p>最后落到工程判断：这套混合精度方案的上限不由 NVFP4 的峰值算力决定，而由校准集覆盖度与 kernel 融合质量决定。校准集覆盖不到的长尾输入会让 amax 估计失准，融合不到位的 amax 统计会吃掉 5–10% 时延，两者都会把“权重降 1/4、batch 提 2–3 倍”的账面收益打折。可执行的动作是把校准步数（32–64 步）、分组粒度（16 元素）、回退阈值三者作为一组联合调参，用一次端到端采样测出实际 batch 上限与 FID 退化，再决定是否收紧回退比例。</p>\n\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-20\">二十 · 回退比例、amax 开销与 latent 还原：这套方案的失效边界</h3>\n<p>这套混合精度方案的收益不是无条件成立的，它有三个明确的失效面。第一个是敏感层回退比例：首末 block 与 adaLN 调制投影必须走 FP8 或 BF16，否则 NVFP4 两级缩放的残余误差会在高噪步被放大，表现为色彩偏移与结构崩坏。回退比例需逐模型校准，且随模型增大而上升——回退越多，权重显存越接近 <span class=\"formula\">$$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$</span> 中 BF16 那一项，1/4 的收益被侵蚀。工程判断是：把回退层清单做成校准产物而非硬编码，按敏感度分数排序截断，保证回退后权重显存仍显著低于纯 FP8 基线，否则量化失去意义。</p>\n<p>第二个失效面是激活在线量化的 amax 统计。每层激活需在 MMA 前求 per-group amax 再量化到 E4M3，这引入额外 kernel；若不能与 attention 及前一算子融合，会吃掉 5–10% 时延收益，直接抵消部分显存带宽红利。伪代码上应把 amax 归约写进 producer 的 epilogue：<ul><li>producer 写出 FP8 激活的同时，用 warp 级 reduce 更新该 group 的 amax 到 TMEM 旁路缓冲；</li><li>consumer 的 tcgen05 MMA 直接读该 scale，不另起 kernel；</li><li>无法融合的层退化为静态校准 scale，用校准集 32–64 步统计的 per-group amax 替代在线统计。</li></ul>代价是静态 scale 对分布外 prompt 更脆弱，需在敏感层保留在线路径。</p>\n<p>第三个失效面在 VAE 解码前的数值还原。latent 必须在进入解码器前还原为 BF16，否则解码器数值漂移导致细节糊化，量化带来的吞吐收益被画质退化抵消。这一步不是可选优化而是正确性要求：扩散主干可以容忍 NVFP4×FP8 的误差，解码器不能。系统代价上，还原引入一次 latent 张量的 dtype 转换与可能的显存往返，在 1024² 采样下相对主干前向可忽略，但若与 VAE 的 tiling 策略冲突会放大峰值显存。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>表现</th><th>系统代价</th></tr></thead><tbody><tr><td>敏感层未回退</td><td>色彩偏移、结构崩坏</td><td>回退比例上升侵蚀 1/4 显存收益</td></tr><tr><td>amax 未融合</td><td>额外 kernel 插入</td><td>吃掉 5–10% 时延收益</td></tr><tr><td>latent 未还原 BF16</td><td>细节糊化</td><td>画质退化抵消吞吐收益</td></tr></tbody></table>\n<p>规模上限因此由两个量决定：校准集覆盖度决定敏感层清单是否可信，kernel 融合质量决定 amax 开销能否压到可忽略。收益集中在显存带宽受限的大分辨率采样——1024² 下 batch 提升 2–3 倍的前提是回退比例受控且 amax 已融合；任一条件不满足，就该退回纯 FP8 权重路径，而不是继续压 NVFP4 的组大小。</p>\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-21\">二十一 · 请求形态与批大小的耦合关系</h3>\n<p>NVFP4 混合精度量化的收益不是无条件兑现的，它首先要求请求形态落在“显存带宽受限、单次前向计算量大”的区间里。DiT 采样的显存占用由三部分构成：主干权重、激活工作集、以及采样过程中保留的中间张量。权重按 <span class=\"formula\">$$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$</span> 收缩后，原本卡死 batch 的那一项被压到四分之一，于是 batch 才有从 1 抬到 2–3 倍的空间。但这条公式里 scale overhead 是不可忽略的：每 16 个权重元素附一个 FP8 per-group scale、再叠一个 FP32 二级 scale，等效于在 4 bit 权重之上再加约 0.5–0.75 bit 的元数据，所以实际权重占用略高于名义的 1/4，批大小提升也不会线性等于 4 倍。</p>\n<p>请求形态的判定标准很直接：单请求是否已经把一张 B200 的显存吃到接近上限。1024² 单图采样正是这种形态——分辨率高、latent token 数多、每步前向的激活张量尺寸大，batch=1 时显存余量不足以再塞一个样本，Tensor Core 的 NVFP4 通路处于半饥饿状态。此时量化把权重腾出的显存直接换成并发度，吞吐随 batch 近似线性上升，是收益最纯的场景。反过来，若请求是 512² 或更小的图，单请求显存占用本来就低，batch 早已能开到较大值，权重压缩带来的边际并发增益迅速衰减，而激活在线量化的额外 kernel 开销却是固定的，净收益被摊薄。</p>\n<p>长度分布在这里指采样步数与分辨率两个维度。步数决定激活工作集被复用的次数：32–64 步的校准区间对应的是典型采样长度，步数越多，每步都要重新做一次激活 amax 统计与在线量化，量化开销按步数线性累加；步数少（少步蒸馏后的 4–8 步）时，固定开销占比反而更高。分辨率则决定单步前向的算术强度，1024² 下 GEMM 的 M 维足够大，tcgen05 MMA 能跑满，NVFP4 的峰值算力才有被消费的机会；低分辨率下 M 维偏小，MMA 的 tile 利用率下降，量化带来的位宽红利被调度开销抵消。</p>\n<p>一个具体的工程判断：把 batch 提升 2–3 倍之后，单步时延会因并发而上升，但每图摊薄时延下降，SLO 应以吞吐（图/秒）为主指标而非单请求尾延迟。若业务侧对首图时延敏感，则需要把大批拆成小批加连续批处理，让新请求在旧请求的采样步之间插入，这属于调度层的事，量化只负责把显存天花板抬高。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-22\">二十二 · 并发上升后暴露的带宽与算力配比问题</h3>\n<p>batch 提升 2–3 倍并不自动等于吞吐提升 2–3 倍，因为量化改变的是权重位宽，而每步前向的访存量结构也随之改变。设单步前向的权重访存为 <span class=\"formula\">$$B_{W}=W_{\\text{eff}}\\cdot\\frac{1}{\\text{bit-width ratio}}$$</span>，激活访存为 <span class=\"formula\">$$B_{A}=A_{\\text{FP8}}\\cdot\\text{batch}$$</span>，则总访存随 batch 线性增长的那一项是激活，而权重项被压缩后近似与 batch 无关。这意味着小 batch 时权重访存占主导，量化收益最大；batch 抬到 2–3 倍后，激活访存开始与权重访存同量级，HBM 带宽重新成为瓶颈，此时继续加 batch 的边际吞吐收益递减。</p>\n<p>这个转折点决定了“负载配方”的上限。工程上应把 batch 设在激活访存尚未压过权重访存的位置，而不是一味顶到显存极限。若把 batch 顶满，虽然显存还够，但每步前向的 HBM 流量被激活撑爆，SM 在等数据，NVFP4 的 Tensor Core 空转，实测吞吐反而低于中等 batch。判断方法是在候选 batch 上测每步的 HBM 利用率与 MMA 占用率：前者接近饱和而后者偏低，说明已经越过转折点。</p>\n<p>并发还牵动激活在线量化的 kernel 插入位置。每个线性层前都要对激活做一次 amax 归约再量化到 FP8（E4M3），这个归约若不能与上游 attention 或前一层的 epilogue 融合，就会在流水中插入同步点。batch 越大，这次归约要扫的元素越多，插入的 kernel 时间越长。5–10% 的时延收益被吃掉这一代价，在小 batch 时占比不明显，在大 batch 时因为归约规模膨胀而放大，正好撞上吞吐收益递减的区间，形成“越加 batch 越不划算”的复合效应。</p>\n<p>例子：同一张 B200 上，batch=1 时权重访存主导，量化后单步时延下降明显；batch 抬到 2–3 倍后，若 amax 归约未融合，每步多出的归约 kernel 与激活流量叠加，端到端吞吐的提升幅度会明显小于 batch 的提升幅度。此时正确的动作不是继续加 batch，而是先把归约融进 attention 的 epilogue 或前一层输出，把固定开销压掉，再重新寻找 batch 拐点。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-23\">二十三 · 敏感层回退比例对负载配方的反向约束</h3>\n<p>负载配方不能只看 batch，还要看回退比例。首末 block 与 adaLN 调制投影必须回退到 FP8 或 BF16，否则两级缩放的误差在高噪步被放大，表现为色彩偏移与结构崩坏。回退比例 <span class=\"formula\">$$r_{\\text{fb}}=\\frac{W_{\\text{fallback}}}{W_{\\text{total}}}$$</span> 直接侵蚀权重显存收益：回退部分按 FP8 存则占 1/8 而非 1/4，按 BF16 存则回到 1/2。于是实际权重占用变成 <span class=\"formula\">$$\\text{Mem}_{W}=(1-r_{\\text{fb}})\\cdot\\frac{1}{4}W_{\\text{BF16}}+r_{\\text{fb}}\\cdot\\frac{1}{8}W_{\\text{BF16}}$$</span>（假设回退层走 FP8），可支撑的 batch 上限随之下降。</p>\n<p>关键在于回退比例随模型增大而上升。大模型的 block 数多，首末 block 占比看似下降，但调制投影与敏感中间层的绝对数量增加，逐模型校准后往往需要回退更多层才能守住画质。回退过多会把 2–3 倍的 batch 提升压回到 1.5 倍量级，显存红利被吃掉大半。这就是规模上限的第一条约束：负载配方里的 batch 目标必须按校准后的实际回退比例反算，而不是按名义 1/4 权重算。</p>\n<p>校准集覆盖度是第二条约束。32–64 步前向的校准只采样了有限的噪声水平与条件输入，若线上请求的条件分布（提示词复杂度、分辨率、长宽比）落在校准集之外，敏感度分数会失准，本该回退的层被误判为可量化，画质退化在特定请求上集中爆发。负载配方因此要包含请求分布的监控：当线上请求的 FID 退化超过阈值，说明校准集没覆盖到这类形态，需要补校准而非调 batch。</p>\n<p>例子：一个以 1024² 单图为主的业务，校准后回退比例落在中等水平，batch 从 1 抬到 2–3 倍，吞吐按图/秒计提升明显；若同一套权重拿去服务大量 768×768 与极端长宽比请求，回退层的保护在这些形态上不足，色彩偏移先在小批量请求上出现，此时正确的处置是把这类请求路由到 FP8 全量路径，而不是在 NVFP4 路径上继续压 batch。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-24\">二十四 · 与采样步数、CFG 批合并叠加时的配方重算</h3>\n<p>NVFP4 只改数值格式与算子通路，不改采样步数与调度，因此它能与步数蒸馏、CFG 批合并叠加——但叠加之后负载配方必须重算。CFG 批合并把无条件与有条件两条前向拼成一个 batch 维度翻倍的 GEMM，等效于把有效 batch 乘以 2。若原本 batch 已顶到显存上限，CFG 合并后有效 batch 翻倍会直接撞墙，量化的显存红利被 CFG 吃掉。配方上应把 CFG 合并视为 batch 的乘数，先算 <span class=\"formula\">$$B_{\\text{eff}}=B_{\\text{req}}\\cdot(1+\\mathbb{1}_{\\text{CFG}})$$</span>，再对照量化后的显存预算定 <span class=\"formula\">$$B_{\\text{req}}$$</span>。</p>\n<p>步数蒸馏把 32–64 步压到少步，每步的激活 amax 统计次数随之减少，固定开销占比下降，但同时每步的计算密度上升，单步时延成为主导。此时 batch 的提升对吞吐的贡献更直接，因为固定开销被摊到更少的步上。反过来，未蒸馏的长步数采样里，每步都要重做激活量化，量化开销按步数线性累加，配方上应优先保证 amax 归约与 attention 融合，否则 5–10% 的时延损失在长步数下被重复计费几十次。</p>\n<p>一个具体机制层面的判断：CFG 合并后 batch 维翻倍，tcgen05 MMA 的 tile 划分会重新切分 M 维，若 M 维超过 MMA 的最佳 tile 尺寸，会引入额外的边界 tile 浪费。配方上应让 <span class=\"formula\">$$B_{\\text{eff}}$$</span> 落在 tile 尺寸的整数倍附近，避免尾部 tile 拉低 MMA 利用率。这与纯显存视角的 batch 上限是两个独立约束，取二者较小值才是可用 batch。</p>\n<p>例子：一个业务同时开启 CFG 合并与少步蒸馏，名义 batch 上限按显存算是 2–3 倍，但 CFG 把有效 batch 翻倍后已越过 MMA tile 的整数倍边界，实际吞吐提升小于预期；把请求 batch 下调一档使有效 batch 对齐 tile，吞吐反而回升。这说明负载配方不是单调的“越大越好”，而是要在显存、带宽、tile 对齐三个约束的交集里取点。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-25\">二十五 · 负载不对时的失败形态与识别信号</h3>\n<p>负载配方错配时，失败不会以报错形式出现，而是以画质退化与吞吐倒挂两种形态暴露。第一种是敏感层回退不足：高噪步的激活动态范围大，NVFP4 两级缩放的 per-group 误差在此被放大，输出出现色彩偏移与结构崩坏。识别信号是固定种子下对比 BF16 基线的色彩直方图偏移与结构相似度下降，且退化集中在采样前几步。处置是提高回退比例或把首末 block 与调制投影锁死在 FP8/BF16，代价是显存收益收窄。</p>\n<p>第二种是激活 amax 统计未融合导致的时延倒挂：额外 kernel 吃掉 5–10% 的时延收益，在 batch 已越过带宽转折点时，这部分损失无法被吞吐摊薄，端到端表现为“量化后反而更慢”。识别信号是 profiler 里每层前多出的归约 kernel 与流水中断点，以及 HBM 利用率与 MMA 占用率同时偏低。处置是把归约融进上游 epilogue，或对激活改用静态 scale 跳过在线统计，代价是动态范围适配变差。</p>\n<p>第三种是 VAE 解码前的 latent 未还原为 BF16：解码器对数值漂移敏感，细节糊化，量化在主干上省下的画质余量被解码器吃掉。识别信号是高频细节的能量下降与纹理区域的模糊，且退化与采样步数无关、只与解码路径相关。处置是在 VAE 入口插入 BF16 还原，代价是一次额外的类型转换与一份 BF16 latent 的临时显存。</p>\n<p>这三种失败形态的共同点是：它们都不改变吞吐的数字表面，却改变业务可接受度。负载配方的工程判断因此要把画质监控纳入配方闭环——batch 与回退比例不是一次校准就固定的常量，而是随请求分布漂移需要重算的变量。当线上请求形态偏离校准集，先补校准、再调 batch，顺序不能反。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-26\">二十六 · 配方参数的取值边界与监控闭环</h3>\n<p>把负载配方写成可执行的参数集：请求形态限定在大分辨率单图采样，batch 目标按量化后显存预算与 MMA tile 对齐取交集，回退比例按逐模型校准结果反算，激活量化路径要求 amax 归约与 attention 或前层 epilogue 融合。这四个参数里，batch 与回退比例是互相拉扯的一对——回退多则 batch 少，回退少则画质险，配方点落在画质可接受前提下的最大 batch。</p>\n<p>监控闭环需要三个信号：每步的 HBM 利用率与 MMA 占用率用于判断是否越过带宽转折点；固定种子对比基线的色彩与结构指标用于判断回退是否足够；profiler 里归约 kernel 的插入位置用于判断融合是否生效。三者任一越界，配方就要重算，而不是靠调大 batch 掩盖。规模上限受校准集覆盖度与 kernel 融合质量约束，这两项决定了配方能否随模型增大而线性外推。</p>\n<p>最后落到一个具体机制上：tcgen05 MMA 消费 NVFP4×FP8 时，反量化在 epilogue 融合，累加器保持 FP32，这条通路的前提是权重按 16 元素一组打包、scale 随组走。负载配方若把 batch 抬到让激活访存压过权重访存，epilogue 的反量化吞吐就会成为新的瓶颈，此时再压缩权重位宽已无收益，应该转向激活侧的融合优化。配方的边界不在显存数字上，而在“权重访存与激活访存谁主导”这条分界线上。</p>\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-27\">二十七 · 硬件档位：单卡 B200 的显存账本</h3>\n<p>部署配方的第一层是硬件档位。本算法的收益锚点非常明确：单张 B200、1024² 单图采样、批大小被显存卡死。因此档位选择不是“越大越好”，而是“刚好让权重显存降到 BF16 的 1/4，把省出来的空间全部换成 batch”。显存账本按公式估算：</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$</div>\n<p>这里权重项从 1 降到 1/4，激活项按 FP8 计为 1/8，scale overhead 是每 16 元素一组的 FP8 per-group scale 加每张量或每组一个 FP32 二级 scale。工程判断上，scale overhead 必须计入预算：16 元素一组意味着每组一个 FP8 scale，即权重元素数的 1/16 字节量级，虽然远小于权重本体，但在回退层比例上升时会被放大。档位决策的判据是：先按 BF16 权重算出当前 batch 上限，再把权重项替换为 1/4，看释放出的显存能否支撑 2–3 倍 batch；若不能，说明回退比例过高或 scale overhead 失控，应先收紧回退层清单而不是加卡。单卡档位的好处是并行拓扑退化为零通信，所有省下的带宽都留给权重读取与激活在线量化。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-28\">二十八 · 并行拓扑：把 TP 留给回退层之外的场景</h3>\n<p>本算法在单卡档位下不需要张量并行，但部署配方必须给出拓扑的判定规则，否则读者在 batch 仍不够时会误加 TP。规则是：优先加 batch，其次加数据并行副本，最后才考虑 TP。原因是 NVFP4 权重的收益来自带宽节省，TP 会把每层权重切分后引入 all-reduce，通信量与激活规模成正比，而激活已经是 FP8，切分收益被稀释。若必须上多卡，拓扑应按“回退层集中”原则布置：首末 block 与 adaLN 调制投影走 FP8/BF16 回退，这些层的权重精度高、显存占用相对大，把它们放在同一副本内可避免跨卡精度不一致带来的数值漂移。并行拓扑的代价指标是每步 all-reduce 的字节数；在 1024² 采样下，激活张量的空间维度远大于通道维度，TP 切通道的通信效率低于切空间，因此空间切分（若框架支持）优于通道切分。具体例子：当单卡 batch 提升 2–3 倍后仍不满足吞吐目标，先复制副本做数据并行，让每个副本独立跑完整前向，避免任何集合通信进入采样循环。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-29\">二十九 · 量化方案：回退层清单是配方的主参数</h3>\n<p>量化方案在部署配方里不是一个开关，而是一张分层清单。主干线性层：权重 NVFP4（E2M1 + 两级微缩放），激活在线量化到 FP8（E4M3），tcgen05 MMA 直接消费 NVFP4×FP8，累加器 FP32，反量化在 epilogue 融合。回退层：首末 block 与 adaLN 调制投影走 FP8 回退，必要时首末 block 保持 BF16。核心量化关系为：</p>\n<div class=\"formula\">$$w_q=\\mathrm{round}_{E2M1}\\!\\left(\\frac{w}{s_1 s_2}\\right),\\quad \\hat{w}=w_q\\cdot s_1\\cdot s_2$$</div>\n<p>其中 $s_1$ 为 FP8 per-group scale、$s_2$ 为 FP32 二级 scale，打包粒度为 16 元素一组。配方的主参数是回退比例，它必须逐模型校准：校准集跑 32–64 步前向，按 block 统计 per-group amax 与敏感度分数，敏感度高的 block 进回退清单。代价侧要盯两件事：回退比例随模型增大而上升，回退过多会侵蚀显存收益，把 1/4 的权重项拉回 1/2 甚至更高；激活在线量化的 amax 统计引入额外 kernel，若与 attention 融合不好会吃掉 5–10% 时延收益。工程判断是：回退清单以“首末 block + 调制投影”为基线，只在敏感度分数明确越界时扩列，扩列后用显存账本重算 batch 上限，确认收益仍在 2–3 倍量级再定稿。具体例子：若把中间若干 block 也回退到 BF16，权重项上升会直接压缩 batch，吞吐反而低于纯 FP8 方案，此时应回退配方而不是继续加回退层。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-30\">三十 · KV 与激活策略：latent 还原点决定画质下限</h3>\n<p>扩散推理没有自回归 KV cache，本算法语境下的“KV 策略”应理解为激活与中间张量的驻留策略，以及 VAE 解码前的精度还原点。配方规定：采样循环内激活保持 FP8 在线量化，中间 latent 以 BF16 或 FP8 驻留由显存预算决定；VAE 解码前必须把 latent 还原为 BF16，避免解码器数值漂移导致细节糊化。这一步是画质下限的守门点：量化收益若被解码退化抵消，整条配方失效。驻留策略的代价指标是峰值显存与带宽往返次数；把 latent 全程压在 FP8 可省显存，但还原时的反量化 kernel 会插入一次全张量读写，在 1024² 下这次读写的带宽开销与一次注意力层的量级相当，因此还原点应尽量靠近 VAE 入口，减少中间反复转换。具体例子：批内多图共享同一步数调度时，latent 按 batch 维拼接驻留，还原为 BF16 时一次性转换整批，避免逐图转换带来的 kernel 启动开销。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-31\">三十一 · 调度参数：批大小、步数与 CFG 的耦合</h3>\n<p>调度参数在本配方里围绕一个目标：让 batch 吃满省出来的显存，同时不破坏数值稳定性。批大小由显存账本反推，取 2–3 倍于 BF16 档位的上限，并留出激活在线量化 amax 统计的临时缓冲。步数保持 32–64 步不变——本算法只改数值格式与算子通路，不改采样步数与调度，因此可与步数蒸馏、CFG 批合并叠加；叠加时批大小要按合并后的有效 batch 重算，CFG 批合并把条件与非条件拼进同一批，等效 batch 翻倍，显存账本里的激活项随之翻倍，必须在配方里显式预留。调度参数的稳定性约束是：高噪步的量化误差被放大最明显，首末 block 回退正是为这一段兜底，因此调度上不应在高噪步做额外的批扩张或分辨率跳变。代价指标是每步时延与吞吐的比值；当激活 amax kernel 未融合时，每步多出的 5–10% 时延会随步数线性累积，配方应优先选择已融合该统计的注意力实现，而不是靠减少步数去补偿。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-32\">三十二 · 可复现的配置思路：从校准到定稿的四步</h3>\n<p>把上述五层收拢成一条可复现路径，按顺序执行，每步都有明确的通过判据。</p>\n<ul>\n<li>第一步，校准：用覆盖目标分辨率与提示分布的校准集跑 32–64 步前向，按 block 记录权重/激活 per-group amax 与敏感度分数，产出回退层候选清单。判据是候选清单的首末 block 与调制投影必须在内。</li>\n<li>第二步，打包：权重按 16 元素一组打包为 NVFP4，附 FP8 per-group scale 与 FP32 二级 scale；激活通路配置为在线量化到 FP8（E4M3），确认 tcgen05 MMA 的 NVFP4×FP8 通路与 FP32 累加器在 epilogue 融合反量化。</li>\n<li>第三步，显存核算：按 <span>Mem</span> 公式重算权重项、激活项与 scale overhead，得出 batch 上限，验证相对 BF16 档位有 2–3 倍提升；若不足，先缩回退清单再谈加卡。</li>\n<li>第四步，稳定性验收：检查首末 block 与 adaLN 调制是否确实回退，检查 VAE 解码前 latent 是否还原为 BF16，检查激活 amax 统计是否与 attention 融合；三项任一不满足，画质退化或 5–10% 时延损失就会吃掉配方收益。</li>\n</ul>\n<p>这条路径的关键工程判断是：配方的主参数不是 batch，而是回退比例与 kernel 融合质量。回退比例决定显存收益的上限，融合质量决定时延收益的下限，两者共同决定 1024² 采样在单张 B200 上能否稳定跑在 2–3 倍 batch 的吞吐档位。定稿时把回退清单、打包粒度、还原点与调度参数一起写入部署配置，任何一项单独调整都要回到显存核算重跑一遍，避免局部优化侵蚀整体收益。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-33\">三十三 · 部署配方的边界：回退比例、融合质量与显存红利的三角约束</h3>\n<p>这套配方在单张 B200 上的可复现思路可以写成一张四行的配置表：硬件档位固定为单卡 B200（不引入 NVLink 域内并行，因为 1024² 单图采样的并行收益被通信开销吃掉）；量化方案固定为 NVFP4 权重 × FP8 激活、FP32 累加器，敏感层回退 FP8；KV 策略在 DiT 采样中并不存在自回归 KV cache，真正需要管的是 latent 缓冲与 attention 的临时工作区，因此“KV 策略”在这里退化为激活缓冲的复用与 epilogue 融合的写入时机；调度参数只调 batch 上限与校准步数，不改采样步数与 CFG 结构。关键在于这张表不是无条件的——它的收益区间由三个量共同决定：回退层占比 $r$、激活量化 kernel 的融合度 $f$、以及显存节省能否转化为 batch。用显存公式表达，实际收益为</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{DiT}}\\approx(1-r)\\cdot\\frac{1}{4}W_{\\text{BF16}}+r\\cdot\\frac{1}{2}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$</div>\n<p>当 $r$ 从 0 上升到 0.3，权重侧的显存节省从 4 倍缩到约 2.5 倍，batch 提升 2–3 倍的结论就不再成立。这正是“敏感层回退比例随模型增大而上升”的工程含义：模型越深，首末 block 与 adaLN 调制投影在总权重中的占比越高，回退越多，显存红利被侵蚀得越快。校准集跑 32–64 步前向得到的敏感度分数，本质上是在为 $r$ 定一个下限——低于这个下限，高噪步的两级缩放误差被放大，表现为色彩偏移与结构崩坏；高于这个下限，吞吐收益开始让位于安全边际。</p>\n<p>第二个边界是 kernel 融合质量。激活在线量化需要对每个 block 统计 per-group amax，这一步若不能与 attention 的 softmax 或 GEMM 的 prologue 合并，就会插入独立 kernel，吃掉 5–10% 的时延收益。判断是否值得开激活量化的粗略准则是：设单步前向时延为 $T$，量化 kernel 引入的额外开销为 $\\Delta T$，则只有当显存节省带来的 batch 增益满足</p>\n<div class=\"formula\">$$\\frac{B_{\\text{new}}}{B_{\\text{old}}}\\cdot\\frac{T}{T+\\Delta T}&gt;1$$</div>\n<p>时，激活量化才是净正收益。1024² 下 batch 提升 2–3 倍意味着左侧第一项足够大，即便 $\\Delta T/T$ 落在 5–10% 区间仍能覆盖；但若分辨率降到 512²、显存不再是瓶颈，同一配方就会变成纯开销。这就是“收益集中在显存带宽受限的大分辨率采样”的量化解释，也是配方不可跨分辨率照搬的原因。</p>\n<p>第三个边界是数值链路的末端。VAE 解码前必须把 latent 还原为 BF16，否则解码器的数值漂移会让细节糊化，画质退化抵消掉全部量化收益。这一条在部署上不是可选优化而是硬约束：它意味着量化通路的出口必须有一个显式的精度提升点，且这个点的位置不能随意前移——把还原点放到 VAE 内部会污染解码器的中间激活。表格给出配方各环节的失效条件与代价归属：</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>敏感层回退</td><td>回退比例低于校准下限</td><td>色彩偏移、结构崩坏，需重跑校准</td></tr><tr><td>激活在线量化</td><td>amax 统计未与 attention 融合</td><td>5–10% 时延收益被抵消</td></tr><tr><td>latent 还原</td><td>还原点前移或缺失</td><td>细节糊化，画质退化抵消吞吐</td></tr><tr><td>batch 放大</td><td>分辨率下降、显存不再受限</td><td>量化开销转为净负，吞吐反降</td></tr></tbody></table>\n<p>把这三条边界合起来看，配方的适用规模上限由校准集覆盖度与 kernel 融合质量共同封顶：校准集覆盖不到的层，敏感度分数不可信，只能保守回退；融合做不好的算子，激活量化的收益被 kernel 启动开销吞掉。工程判断因此落在两件事上——先用 32–64 步校准把 $r$ 压到显存收益仍显著的水平，再确认 amax 统计已并入既有 kernel 的 prologue 而非独立 launch。这两步任一不满足，配方就应退回纯 FP8 权重路径，而不是靠调 batch 硬撑。</p>\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-34\">三十四 · 显存账本：权重降了，激活没降</h3>\n<p>NVFP4 混合精度在 DiT 上的第一笔收益记在权重上，但系统代价的核算必须把激活、scale 元数据与工作区一起算进去。按本卷给出的记账式，主干显存近似为 BF16 权重的四分之一、FP8 激活的八分之一，再加 scale 开销。关键在于：权重从 BF16 压到 NVFP4 是 4 倍压缩，而激活只从 BF16 压到 FP8 是 2 倍压缩，两者不同比例下降，意味着当 batch 继续放大时，激活项会逐渐取代权重项成为显存占用的主导。1024² 采样下每张图的 latent token 序列很长，注意力与 MLP 的中间激活随 batch 线性增长，权重却是常数项——这正是“权重降 4 倍、batch 只提升 2–3 倍”而非 4 倍的直接原因。工程判断是：显存预算表要按“常数项 + 每样本项”两栏建模，权重与 scale 进常数栏，激活与 KV 类缓冲进每样本栏，再解出 batch 上限。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead},\\qquad B_{\\max}\\approx\\frac{M_{\\text{free}}-\\frac{1}{4}W_{\\text{BF16}}-\\text{scale}}{A_{\\text{per-sample}}}$$</div>\n<p>scale 开销不可忽略：权重按 16 元素一组打包，每组带一个 FP8 per-group scale，再加一个 FP32 二级 scale，等效于每 16 个 4 bit 元素附加约 1 字节多的元数据，压缩比从名义 4 倍回落到略低。回退层更贵——首末 block 与 adaLN 调制投影走 FP8/BF16，这部分权重不享受 4 倍压缩，回退比例越高，常数项越大。规模上去后第一个崩点往往不是算力而是这条常数项：当回退比例随模型增大而上升，显存收益被侵蚀，batch 上限回落，吞吐随之掉档。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-35\">三十五 · 带宽与 Tensor Core 利用率的错配</h3>\n<p>NVFP4 的算力峰值只有在数据供给跟得上时才兑现。tcgen05 MMA 一次前向消费 NVFP4×FP8、FP32 累加，反量化在 epilogue 融合，这条通路的算术强度被权重压缩抬高——同样一次 MMA 搬运的权重字节只有 BF16 的四分之一，理论上每字节喂进的 MAC 数翻四倍。但激活侧仍是 FP8，且激活在线量化需要先统计 amax 再缩放，这个统计 kernel 与主 GEMM 之间存在串行依赖。若 amax 统计未能与 attention 或前一算子融合，就多出一次全量激活的读+写，带宽账上等于把权重压缩省下的流量又吐回去一部分。本卷给出的量级是：融合不好会吃掉 5–10% 的时延收益。</p>\n<p>具体例子：一个 1024² 采样步里，主干若干线性层的权重读取因 NVFP4 降至四分之一，但每个线性层的输入激活都要过一次 amax 归约。若归约单独起 kernel，激活被读两遍（归约一遍、GEMM 一遍），在带宽受限的大分辨率场景下这部分额外流量与权重节省同数量级，净收益被压缩。工程上的做法是把 amax 统计塞进上游算子的 epilogue，让激活只写一次、读一次，把“额外 kernel”变成“融合进已有 kernel 的一小段”。这也是规模上限受 kernel 融合质量约束的原因：融合做得好，带宽红利全额兑现；做不好，规模越大、激活越多，被吃掉的时延越多。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-36\">三十六 · 通信：分离式部署下权重与激活的两本账</h3>\n<p>单卡 B200 是本文的部署档位，但一旦进入预填/解码分离或多卡并行，NVFP4 的通信代价结构就变了。权重压缩对通信是单向利好：权重的 all-gather 或参数同步流量按 4 倍缩减，张量并行下每层切分的权重广播成本显著下降。但激活压缩只有 2 倍，且激活在线量化发生在通信之前还是之后，决定了链路上跑的是 FP8 还是 BF16。若在 all-reduce 前保持 BF16 激活、归约后再量化，链路流量按 BF16 计，权重侧省下的带宽在激活侧被抵消；若先量化到 FP8 再通信，则需保证各 rank 的 per-group scale 语义一致，否则归约后的数值与单卡路径不一致，画质退化从量化误差变成通信引入的偏差。</p>\n<p>代价判断：在 NVLink 5 域内，带宽相对宽裕，激活通信的格式选择对时延影响有限；跨节点走 NIXL 或 NCCL 的链路才是瓶颈所在。规模上去后，第二个崩点常出现在这里——权重省了 4 倍流量，激活只省 2 倍，总通信量下降比例小于权重压缩比，当并行度提高、每卡分到的激活份额不变而权重份额变小，通信中激活占比上升，链路从“权重主导”翻转为“激活主导”。此时继续加并行度的边际收益递减，需要转向减少激活通信次数（如算子融合减少中间张量落盘）而非继续压权重精度。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-37\">三十七 · 功耗与热：峰值算力兑现后的新约束</h3>\n<p>NVFP4 让 Tensor Core 在同样功耗预算下做更多 MAC，但功耗并不会因为权重变小而线性下降。B200 的功耗大头在 MMA 阵列与显存子系统：权重读取流量下降会减轻 HBM 侧功耗，但算力利用率提高意味着 MMA 阵列更长时间处于高占用，阵列功耗上升。净效果取决于算术强度提升与利用率提升的相对幅度——在带宽受限的大分辨率采样里，原先阵列空转等数据，压缩后数据供给改善、阵列忙起来，整卡功耗向峰值靠拢。这意味着 batch 提升 2–3 倍带来的吞吐增益，在机架级（GB200/GB300 NVL72）上会转化为每机架功耗密度的上升，容量规划必须按“吞吐/瓦”而非单纯“吞吐/卡”核算。</p>\n<p>尾延迟在这里第一次显形：功耗爬升导致时钟回落，长尾请求的采样步时延被拉长。扩散采样的尾延迟结构特殊——单请求由几十步串行组成，任何一步的时延抖动都会累积到端到端；而连续批处理下，一个长请求会拖住同批其他请求的调度槽。NVFP4 把单步算力成本压低后，单步时延的绝对值变小，但抖动占比可能变大：amax 统计 kernel 若在某些步触发额外同步，或回退层（首末 block、调制投影）在特定步集中出现，就会形成周期性尖峰。工程上要把回退层的位置与采样步对齐看——首末 block 在每步都执行，其 FP8/BF16 路径的时延是常数项；调制投影在 adaLN 里每步都算，同样是常数项，不会随步数变化，但会在每步内形成固定的时延下限。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-38\">三十八 · 尾延迟与规模崩点排序</h3>\n<p>把规模放大时的崩点按出现顺序排：先是显存常数项（回退比例上升侵蚀权重收益）卡住 batch 上限；再是激活带宽（amax 统计未融合）吃掉 5–10% 时延收益，让吞吐增益低于预期；然后是通信中激活占比翻转，多卡扩展的边际收益递减；最后是功耗与时钟，表现为尾延迟抬升。这个排序的依据是各代价随规模增长的斜率：权重是常数，激活随 batch 线性，通信随并行度变化，功耗随利用率上升。因此扩容策略应按斜率倒序处理——先修融合（降激活带宽斜率），再调并行拓扑（控通信占比），最后才谈精度进一步压缩。</p>\n<p>尾延迟的具体机制在批调度层：连续批处理把不同采样步的请求混在一批，NVFP4 路径下每步时延短，批内请求的步进节奏加快，调度器换入换出的频率上升。若回退层的 FP8/BF16 路径与 NVFP4 路径的 kernel 启动开销差异大，混批时会出现路径切换的额外开销，表现为批内某些请求的步时延高于同批均值。一个可操作的判断是：把回退层集中到固定的 block 位置后，观察批内步时延的方差——方差主要来自路径切换而非数据依赖时，应把回退层请求单独成批或固定调度槽，牺牲少量批填充率换尾延迟稳定。VAE 解码前的 latent 还原为 BF16 也是一处固定开销，它不随采样步变化，但在端到端尾延迟里占一个不可压缩的常数段，容量规划时要把它从采样吞吐里单独拆出来算。</p>\n<p>最终落在工程判断上：NVFP4 混合精度在 DiT 上的吞吐收益是真实的，但它把系统瓶颈从“权重带宽”搬到了“激活带宽 + 回退常数项 + 通信激活占比”这三处，规模越大，后两者越先咬人。校准回退比例时不能只看画质，要同时看它把常数项抬高了多少；融合 amax 统计时不能只看单 kernel 时延，要看它是否把激活多读了一遍。吞吐账与画质账必须一起记，否则 batch 提升 2–3 倍的数字会在规模上去后被尾延迟和功耗悄悄吃掉。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-39\">三十九 · 规模上去以后，先崩的是显存账本而不是 Tensor Core</h3>\n<p>把权重压到 NVFP4 之后，单卡 B200 上 1024² 采样的瓶颈会从“权重放不下”迁移到“激活与中间张量放不下”。按 <span class=\"formula\">$$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$</span> 估算，权重项确实降到 BF16 的四分之一，但激活项只降到八分之一，且 DiT 的激活在高分辨率下随 token 数线性膨胀，scale overhead（每 16 元素一组的 FP8 per-group scale 加 FP32 二级 scale）在层数多、通道宽时不再是舍入误差级别。于是 batch 从被权重卡死变成被激活卡死：权重省下的显存被更大的 batch 吃掉，吞吐提升 2–3 倍的前提是激活侧仍能塞进剩余 HBM。一旦分辨率继续上探或叠加 CFG 批合并，激活项重新成为主导，NVFP4 的显存红利被摊薄，此时再压权重收益递减。</p>\n<p>带宽侧的账更微妙。权重读取量降到 1/4 意味着每步前向的权重流量大幅下降，但激活在线量化到 FP8 需要一次 amax 统计的读-归约-写回路，这个额外 kernel 若没有和 attention 的 softmax 或 GEMM 的 epilogue 融合，就会在每层插入一次全量激活遍历。代价是定性的：它吃掉 5–10% 的时延收益，恰好抵消掉一部分带宽红利。判断融合质量的标准很直接——看 profiler 里是否出现独立的 reduce 类 kernel 夹在 MMA 与下一个 MMA 之间；若有，说明 amax 统计没有搭上 tcgen05 流水，NVFP4 的带宽优势被这层“税”削平。规模越大、层数越多，这笔税越重，因为它是按层线性累加的固定开销，而权重带宽节省是按字节数摊薄的。</p>\n<p>通信与尾延迟在单卡配方里不显形，但一旦扩展到多卡张量并行或分离式预填/解码，NVFP4 权重会改变集合通信的字节结构：all-gather 的是打包后的 4 bit 权重加 scale，字节数下降，但 scale 的排布若与 NCCL 的对齐粒度不匹配，会出现小包碎片化，反而拉高单次通信的固定时延。尾延迟的来源则集中在敏感层回退上——首末 block 与 adaLN 调制投影走 FP8/BF16，这些层在每步都被执行且无法与主干同精度流水，形成前向首尾两段“慢区”。回退比例随模型增大而上升，回退过多会侵蚀显存收益，这是规模上限的第一个硬约束；第二个是校准集覆盖度，32–64 步前向统计出的 per-group amax 与敏感度分数若没覆盖高噪步的极端激活，两级缩放误差会在这些步被放大，表现为色彩偏移与结构崩坏。</p>\n<p>功耗维度上，NVFP4×FP8 的 MMA 单次运算的能效高于 BF16，但激活在线量化与反量化 epilogue 融合带来的额外数据搬运会推高访存功耗占比；当 batch 被推到显存上限、SM 占用率接近饱和时，功耗墙而非算力墙先到，此时继续加 batch 只会拉长单步时延而不增吞吐。工程判断的落点是：先测激活峰值显存与 amax kernel 的融合率，再决定 batch 上限；若融合率不达标，优先修 kernel 而不是调回退比例，因为后者直接吃掉画质与显存两张牌。</p>\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-40\">四十 · 精度失败的三条主路径与可观测信号</h3>\n<p>NVFP4 混合精度在 DiT 上的精度失败不是随机噪声，而是沿三条固定路径放大：高噪步的权重两级缩放误差、敏感层缺失回退、以及 latent 未还原导致的解码器漂移。第一条路径的机制在于扩散早期步的激活幅值分布最宽，per-group amax 被少数离群元素拉高，<span class=\"inline-math\">$s_1 s_2$</span> 随之变大，E2M1 的 4 位尾数在归一化后落入粗网格，反量化误差在残差累加中被后续 block 逐层放大。诊断信号不是看单层误差，而是看<b>逐 step 的 latent 统计漂移</b>：把同一 seed 的 BF16 参考轨迹与量化轨迹在每个采样步做逐通道均值/方差比对，若漂移在总步数的前 1/4 段就超过阈值，说明首 block 未回退或校准集未覆盖高噪区间。</p>\n<p>第二条路径表现为色彩偏移与结构崩坏，其判据是 adaLN 调制投影的输出偏差——调制向量直接缩放每个 block 的归一化激活，一旦该投影被量化，误差以乘性方式注入所有 token，视觉上就是全局色温偏移与构图塌陷。第三条路径发生在 VAE 解码入口：latent 若以 FP8 直接送入解码器，卷积层的数值漂移会把高频细节抹平，此时采样侧的一切精度指标都正常，只有解码后图像的频域能量分布偏低。工程上把这三条路径分别对应三个监控探针：latent 逐 step 漂移、调制向量相对误差、解码前后 latent 的 BF16 还原校验。</p>\n<div class=\"formula\">$$\\text{drift}_t=\\frac{\\lVert \\hat{z}_t-z_t^{\\text{BF16}}\\rVert_2}{\\lVert z_t^{\\text{BF16}}\\rVert_2},\\quad \\text{gate}=\\mathbb{1}\\big[\\text{drift}_t&gt;\\tau_t\\big]$$</div>\n<p>阈值 <span class=\"inline-math\">$\\tau_t$</span> 按步索引分段设定，高噪段宽、低噪段严，因为低噪步的 latent 已接近流形，任何偏差都直接体现为可见瑕疵。代价方面，逐 step 漂移比对需要保留一份 BF16 参考轨迹，显存开销等于一份 latent 加一份激活快照，在 1024² 单图采样下相对于权重显存的 1/4 压缩仍属可接受；但若把参考轨迹也放进批内并行，batch 有效容量会被吃掉一档，因此生产环境通常只在灰度实例上开探针，全量实例靠离线校准的敏感层清单兜底。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-41\">四十一 · OOM 的真实来源：不是权重而是激活峰值与碎片</h3>\n<p>权重降到 BF16 的 1/4 后仍会 OOM，原因几乎总在激活侧。DiT 的 1024² 采样在注意力与 MLP 之间存在瞬时激活峰值，其大小与 batch、token 数、以及是否融合 amax 统计 kernel 直接相关。公式给出的显存账是<span class=\"inline-math\">$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$</span>，但 scale overhead 常被低估：每 16 元素一组的 FP8 per-group scale 加 FP32 二级 scale，在权重侧是固定开销，在激活侧却是<b>随 batch 线性增长的临时缓冲</b>，且 amax 统计若未与 attention 融合，会额外申请一块与激活同尺寸的归约工作区。</p>\n<p>诊断 OOM 要看分配时间线而非最终占用：用分配器快照区分「峰值常驻」与「碎片空洞」。典型症状是权重加载后空闲显存充足，但第一个采样步就触发 OOM，说明激活峰值加临时工作区超过了预算；另一种症状是 batch 从 N 提到 N+1 时突然失败，而 N 时占用远低于上限，这是碎片化——不同尺寸的临时缓冲交替申请释放，把大块连续区间切碎。工程对策是把 amax 归约工作区做成预分配的固定池，按最大 batch 一次性申请，避免每步重新分配；同时把 VAE 解码阶段的 latent 还原缓冲与采样阶段分离，不让两个阶段的峰值叠加。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>机制</th><th>代价维度</th><th>处置</th></tr></thead><tbody><tr><td>首步即 OOM</td><td>激活峰值 + amax 工作区叠加</td><td>显存峰值</td><td>预分配归约池，融合 amax</td></tr><tr><td>batch+1 失败</td><td>临时缓冲碎片化</td><td>显存碎片</td><td>固定尺寸池化分配</td></tr><tr><td>解码阶段 OOM</td><td>latent 还原缓冲与采样峰值共存</td><td>显存峰值</td><td>阶段间释放采样工作区</td></tr></tbody></table>\n<p>举例：单张 B200 上 1024² 采样，权重 NVFP4 后 batch 可提升 2–3 倍，但若 amax kernel 未融合，每步多出的归约工作区会让实际可达 batch 退回提升前的水平，等于把显存红利全部吃掉。这就是为什么 OOM 诊断必须和 kernel 融合质量一起看。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-42\">四十二 · 批抖动与路由不均：连续批处理下的量化副作用</h3>\n<p>在扩散服务里，批抖动表现为同一实例的 step 时延随 batch 组成剧烈波动，根源是 NVFP4 路径下不同请求的敏感层回退比例不同——同一模型的不同分辨率或不同 prompt 触发的 CFG 合并形态不同，导致部分请求走 FP8 回退分支、部分走 NVFP4 主路径，两条分支的 MMA 形状与 epilogue 反量化开销不一致，混批时 GPU 按最慢分支对齐，快请求被拖慢。诊断信号是<b>按分支统计的 step 时延分布</b>：若 NVFP4 分支的 P50 与 FP8 分支的 P50 差距明显，而混批后的 P99 接近两者之和，说明批内分支异构正在制造抖动。</p>\n<p>路由不均则出现在多实例或多卡拓扑上：请求按到达顺序分配，若某实例恰好承载了更多高噪步长尾请求，其显存与算力占用会持续偏高，而其他实例空闲。机制上这是量化后显存容量变大、单实例可容纳 batch 变多，调度器倾向于把请求堆到已有大 batch 的实例以减少切换，结果形成正反馈。代价是尾延迟尖刺：一个实例的 batch 越堆越大，其单步时延随 batch 非线性上升，最终把整个服务的 P99 拉高。</p>\n<div class=\"formula\">$$T_{\\text{step}}(b)=T_{\\text{fixed}}+\\alpha b+\\beta\\,b^{2},\\quad \\text{jitter}=\\frac{\\mathrm{P99}(T_{\\text{step}})}{\\mathrm{P50}(T_{\\text{step}})}$$</div>\n<p>二次项 <span class=\"inline-math\">$\\beta b^2$</span> 来自注意力在长上下文下的平方增长与批内分支对齐开销。工程判断是给调度器加<b>分支亲和性约束</b>：把走 FP8 回退的请求聚到同一批，NVFP4 主路径请求聚到另一批，宁可牺牲一点批填充率也要消除批内异构；同时对单实例 batch 设硬上限，用多实例横向扩展承接增量，而不是让单实例无限堆批。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-43\">四十三 · 尾延迟尖刺的定位：从 step 时延到 kernel 级归因</h3>\n<p>尾延迟尖刺在扩散服务里通常不是单点故障，而是三个因素叠加：批内分支异构、amax 统计 kernel 与 attention 的串行依赖、以及 VAE 解码阶段的显存回收抖动。定位方法是把一次请求的 step 时延拆成 kernel 级时间线，看尖刺步的 GPU 空闲间隙落在哪个 kernel 之后。若间隙出现在 attention 之后、amax 归约之前，说明归约 kernel 在等 attention 的输出写回，两者未流水化；若间隙出现在采样结束与 VAE 解码之间，说明显存回收触发了同步等待。</p>\n<p>可用事实给出的量化代价是：amax 统计若与 attention 融合不好，会吃掉 5–10% 的时延收益。这个比例在尾延迟上会被放大——因为尖刺步往往正是 batch 最大、激活最宽的那一步，归约工作区的申请与释放都在关键路径上。诊断上要区分「均值损失」与「尾部分损失」：融合不好时均值时延上升 5–10%，但 P99 可能上升更多，因为大 batch 步的归约开销随 batch 线性增长而 attention 是平方增长，两者叠加点在最大 batch 处。</p>\n<ul>\n<li>监控项：逐 step 的 kernel 时间线、GPU 空闲间隙位置、归约工作区申请次数。</li>\n<li>判据：尖刺步的空闲间隙若稳定出现在同一 kernel 边界，即为串行依赖而非偶发。</li>\n<li>处置：把 amax 归约拆成与 attention 重叠的异步流，或改为在 epilogue 中顺带统计，消除独立 kernel。</li>\n</ul>\n<p>举例：1024² 采样在 batch 提升 2–3 倍后，若 amax kernel 仍在默认流上串行执行，最大 batch 步的时延会明显高于线性外推值，表现为周期性尖刺，周期等于 batch 填充达到峰值的节奏。把归约移入 epilogue 后，尖刺消失，均值时延也回到融合前的水平。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-44\">四十四 · 监控体系：三层探针与回滚触发器</h3>\n<p>监控分三层。第一层是<b>数值探针</b>，在灰度实例上跑 BF16 参考轨迹比对，输出逐 step 漂移、调制向量相对误差、解码前后 latent 还原校验三项指标，阈值按步索引分段。第二层是<b>资源探针</b>，采集显存分配时间线、碎片率、amax 工作区申请频次、单实例 batch 水位，用于捕捉 OOM 前兆与批抖动。第三层是<b>服务探针</b>，按分支统计 step 时延分布与 P99/P50 比值，识别批内异构与路由不均。</p>\n<p>回滚触发器要绑定到具体机制而非单一指标。精度回滚的触发条件是漂移在低噪段超阈值或调制向量误差持续偏高，回滚动作是把对应 block 从 NVFP4 切回 FP8 回退，而不是整模型回退——因为敏感层回退比例随模型增大而上升，整模型回退会侵蚀全部显存收益。资源回滚的触发条件是碎片率超过阈值且 batch+1 失败，动作是收缩单实例 batch 上限并触发实例重建，清空碎片。服务回滚的触发条件是 P99/P50 比值越过阈值且分支时延差距显著，动作是启用分支亲和性调度而非降级精度。</p>\n<table class=\"mini\"><thead><tr><th>层</th><th>探针</th><th>触发条件</th><th>回滚动作</th></tr></thead><tbody><tr><td>数值</td><td>逐 step 漂移、调制误差</td><td>低噪段漂移超阈值</td><td>单 block 切 FP8 回退</td></tr><tr><td>资源</td><td>碎片率、分配时间线</td><td>碎片率高且 batch+1 失败</td><td>收缩 batch 上限、重建实例</td></tr><tr><td>服务</td><td>P99/P50、分支时延</td><td>比值越阈值且分支差距大</td><td>启用分支亲和调度</td></tr></tbody></table>\n<p>代价维度上，三层探针各自有开销：数值探针占一份参考轨迹显存与比对算力，只跑灰度；资源探针的分配器快照有采样开销，按分钟级采集；服务探针是纯统计，无额外算力。工程判断是把回滚做成<b>分级降级</b>而非二元开关——先切敏感层回退，再收缩 batch，最后才整模型回退到 FP8，每一级都保留显存收益的一部分。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-45\">四十五 · 回滚后的残余风险与校准闭环</h3>\n<p>回滚不是终点。敏感层切回 FP8 后，NVFP4 主路径与 FP8 回退路径在同一前向中混跑，tcgen05 MMA 需要在两条精度通路间切换，若切换点落在同一 warpgroup 的连续 MMA 之间，会引入流水线气泡，表现为回滚后时延不降反升。诊断信号是回滚前后的 kernel 时间线对比：若回退层的 MMA 与相邻 NVFP4 层之间出现固定间隙，说明精度通路切换未做流水化编排。处置是把回退层按 block 边界成组排列，让切换发生在 block 之间而非层之间，减少切换次数。</p>\n<p>校准闭环的关键是回退比例与校准集覆盖度的匹配。校准集跑 32–64 步前向统计敏感度分数，若校准集只覆盖低噪区间，高噪步的敏感层会被漏标，表现为灰度实例上高噪段漂移超阈值而校准报告正常。闭环做法是把灰度实例的漂移探针结果回流到校准集，按失败步索引补充采样，重新计算敏感度分数并更新回退清单。规模上限受校准集覆盖度与 kernel 融合质量约束：覆盖度不足则回退清单偏保守、显存收益被侵蚀；融合质量不足则 amax 开销吃掉 5–10% 时延收益，两者共同决定 NVFP4 混合精度在特定模型上的实际净收益。</p>\n<p>最后一个工程判断落在回滚的粒度上：按 block 回退优于按层回退，因为 DiT 的残差结构让单个 block 的精度偏差可被后续 block 部分吸收，而按层回退会把整条通路的数值一致性打破，反而放大漂移。回退清单应作为模型产物的一部分随权重一起版本化，任何权重更新都必须重跑校准与灰度探针，否则回退比例与新的敏感度分布失配，精度失败会以色彩偏移的形式在低噪步突然显现。</p>\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-46\">四十六 · 对照轴：先分清“改数值”与“改调度”</h3>\n<p>把 NVFP4 混合精度放回同族算法的坐标系里，第一件要判断的事不是精度高低，而是这条算法动的是哪一层。NVFP4 混合精度只改数值格式与算子通路：权重打包成 E2M1、两级微缩放，激活在线量化到 FP8，tcgen05 MMA 直接消费 NVFP4×FP8 并在 epilogue 融合反量化，累加器保持 FP32。它不改采样步数、不改 CFG 批结构、不改潜空间分辨率调度、不改特征缓存命中逻辑。因此它与“步数蒸馏/直线采样器”“CFG 批合并与条件缓存”“特征缓存与块级跳步”“混合分辨率补丁调度”是正交关系，可以叠加；而与“DiT FP8 注意力与 GEMM”“DiT MX 混合精度分块”“DiT 分块 PTQ 校准”是替代或互补关系，选错会重复付出校准成本却拿不到额外显存收益。</p>\n<p>正交性可以用一个粗粒度的吞吐分解表达。设单步前向的计算时间为 $T_{\\text{comp}}$、权重与激活搬运时间为 $T_{\\text{mem}}$、调度与批处理开销为 $T_{\\text{sched}}$，则单图端到端时延近似为</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx N_{\\text{step}}\\cdot\\max\\!\\big(T_{\\text{comp}},\\,T_{\\text{mem}}\\big) + T_{\\text{sched}},\\qquad \\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$</div>\n<p>NVFP4 混合精度压的是 $T_{\\text{mem}}$ 与权重占用项，步数类算法压的是 $N_{\\text{step}}$，CFG 合并压的是有效批次数，缓存类算法砍的是实际执行的 block 数。四者相乘才是最终吞吐，所以决策表的第一列应当是“当前瓶颈落在哪一项”，而不是“哪种量化更先进”。在单张 B200 跑 1024² 采样、batch 被显存卡死的场景里，$T_{\\text{mem}}$ 与权重占用是主约束，NVFP4 的 1/4 权重占用直接把可容纳 batch 抬升 2–3 倍，这是它相对纯 FP8 的独有位置。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-47\">四十七 · 与纯 FP8 路线对照：误差同级，收益在显存</h3>\n<p>“DiT FP8 注意力与 GEMM”那条路线把权重与激活都放在 E4M3，走 FP8 Tensor Core 通路，工程上更简单：校准只需 per-tensor 或 per-channel scale，激活量化可与 attention 融合得比较干净，几乎没有额外 kernel。NVFP4 混合精度的代价则明确写在机制里：权重按 16 元素一组打包，附 FP8 per-group scale 与 FP32 二级 scale，反量化关系为</p>\n<div class=\"formula\">$$w_q=\\mathrm{round}_{E2M1}\\!\\left(\\frac{w}{s_1 s_2}\\right),\\quad \\hat{w}=w_q\\cdot s_1\\cdot s_2,\\quad \\hat{W}_{g}=\\mathrm{dequant}\\big(s_{g}^{\\text{outer}}\\cdot s_{g}^{\\text{inner}}\\cdot Q_{4}(W_{g})\\big)$$</div>\n<p>两级缩放的意义在于把 per-group 量化误差压到 FP8 同级，因此画质侧 FID 退化通常 &lt;0.5，这与纯 FP8 的误差量级接近；差别在于权重显存降到 BF16 的 1/4，而 FP8 只到 1/2。判断分界由此变得清晰：若瓶颈是显存容量与权重带宽（大分辨率、大 batch、单卡装不下），选 NVFP4 混合精度；若瓶颈是激活侧带宽或算子融合复杂度、且显存尚有余量，纯 FP8 的工程风险更低。一个具体例子：1024² 采样在 B200 上 batch 被显存卡死时，FP8 只能把权重减半，batch 提升有限；NVFP4 把权重压到 1/4，batch 提升 2–3 倍，这才是吃满 NVFP4 峰值算力的前提。</p>\n<p>系统代价要算全：NVFP4 路径多出激活在线量化的 amax 统计 kernel，若与 attention 融合不好会吃掉 5–10% 时延收益；纯 FP8 路径没有这笔开销，但权重带宽红利只有一半。因此当 batch 已经足够大、$T_{\\text{comp}}$ 成为主项时，NVFP4 的边际收益下降，反而那 5–10% 的额外 kernel 开销更显眼。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-48\">四十八 · 与 MX 分块路线对照：缩放粒度与回退策略的取舍</h3>\n<p>“DiT MX 混合精度分块”同样做块级缩放，但缩放轴与打包粒度不同：MX 以固定块共享指数，NVFP4 用 16 元素一组配 FP8 per-group scale 加 FP32 二级 scale。两者都依赖校准集跑 32–64 步前向、按 block 统计 per-group amax 与敏感度分数，因此校准成本相近，不能叠加使用——同一批线性层被两套格式各量化一次只会增加维护面，不会增加收益。选择依据是硬件通路：Blackwell tcgen05 MMA 对 NVFP4×FP8 有原生混合精度通路，一次前向完成，累加器 FP32，反量化在 epilogue 融合；若目标算子栈对该通路支持不完整，MX 分块的落地阻力更小。</p>\n<p>更关键的差别在敏感层处理。NVFP4 混合精度要求首末 block 与 adaLN 调制投影回退到 FP8 或 BF16，否则两级缩放误差会在高噪步被放大，表现为色彩偏移与结构崩坏；回退比例需逐模型校准，且随模型增大而上升，回退过多会侵蚀显存收益。MX 分块路线若采用更细的块粒度，敏感层的回退面积可能更小，但打包与反量化开销更高。工程判断可以写成一条不等式：设回退层占比为 $r$，则实际权重占用约为</p>\n<div class=\"formula\">$$\\text{Mem}_{W}\\approx(1-r)\\cdot\\frac{1}{4}W_{\\text{BF16}}+r\\cdot\\frac{1}{2}W_{\\text{BF16}}$$</div>\n<p>当 $r$ 上升到使 $\\text{Mem}_{W}$ 接近 FP8 水平时，NVFP4 相对纯 FP8 的显存优势被抹平，此时应改用纯 FP8 或缩小回退面积，而不是继续加大量化层。规模上限正受校准集覆盖度与 kernel 融合质量约束：校准集覆盖不到的高噪步分布，会让两级缩放的误差在推理时暴露。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-49\">四十九 · 与分块 PTQ 校准对照：校准是共享资产，不是重复劳动</h3>\n<p>“DiT 分块 PTQ 校准”提供的是方法论：按 block 统计 amax、算敏感度分数、决定哪些层可量化。NVFP4 混合精度是这套方法论的一个消费者，它把校准输出直接映射为 16 元素一组的打包与两级 scale，并把敏感度分数转成回退名单（首末 block、调制投影走 FP8 回退）。因此二者不是竞争关系：先有分块校准给出敏感度排序，再有 NVFP4 决定打包格式与回退比例，是最省成本的组合；反过来，若已有 NVFP4 部署，再做一套独立的 PTQ 校准只会重复 32–64 步前向的统计开销。</p>\n<p>对照时要盯住校准的“可迁移性”。NVFP4 的两级缩放对 per-group amax 的估计误差比单级 FP8 更敏感，因为外层 FP32 scale 要吸收组间动态范围；校准集若只覆盖少数提示词与固定分辨率，组间 amax 估计会偏，回退比例被迫调大。系统代价体现在部署侧：校准一次要跑 32–64 步前向，属于离线成本，但回退比例调大是线上成本，直接吃掉显存红利。具体例子：同一模型若把首末 block 与 adaLN 调制全部回退到 BF16，权重占用从 1/4 回升，1024² 下 batch 提升从 2–3 倍缩水；因此校准的目标不是“全部量化”，而是“用最小回退面积换 &lt;0.5 的 FID 退化”。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-50\">五十 · 与调度类算法叠加：叠加顺序决定收益是否被吃掉</h3>\n<p>与“潜空间一致性少步采样”“整流流直线采样器”叠加时，NVFP4 不改进采样器，只降低每步的权重带宽与显存占用；叠加后 $N_{\\text{step}}$ 下降、单步 $T_{\\text{mem}}$ 下降，两者相乘，端到端收益最明显。但要注意一个反直觉点：步数减少后，高噪步的比例上升，而首末 block 与调制层的回退正是为高噪步准备的，因此少步采样场景下回退比例不能压缩，否则色彩偏移更易暴露。</p>\n<p>与“CFG 批合并与条件缓存”叠加时，CFG 合并把无条件与有条件前向拼成一个批次，等效 batch 翻倍，正好放大 NVFP4 的显存红利：权重占用降到 1/4 后，合并后的批次仍能装进单张 B200。与“特征缓存与块级跳步”叠加时，跳步减少实际执行的 block 数，被跳过的 block 不再产生权重带宽需求，NVFP4 的收益集中在未跳过的 block 上；此时若回退层恰好落在常被跳过的首末 block，回退的显存代价会被部分抵消，这是可以主动利用的调度—量化协同。</p>\n<p>与“阶段级扩散服务流水”“VAE 分块并行解码”叠加时，要守住机制里的一条硬约束：VAE 解码前必须把 latent 还原为 BF16，避免解码器数值漂移导致细节糊化。流水线切分若把还原点放在错误阶段，量化收益会被画质退化抵消。系统代价上，NVFP4 降低的是 DiT 主干的权重带宽，VAE 解码器的带宽与显存并不因此受益，容量规划时要把两部分分开核算。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-51\">五十一 · 决策表与适用条件</h3>\n<p>下表把同族算法按“动哪一层、主收益、主要代价、适用条件”四列对齐，选择时先定位瓶颈项，再看代价是否落在可接受侧。</p>\n<table class=\"mini\"><thead><tr><th>算法</th><th>改动层</th><th>主收益</th><th>主要代价</th><th>适用条件</th></tr></thead><tbody>\n<tr><td>NVFP4 混合精度</td><td>权重格式 + 算子通路</td><td>权重显存 1/4，1024² batch 提升 2–3 倍</td><td>敏感层回退、amax kernel 吃 5–10% 时延</td><td>显存/权重带宽受限的大分辨率采样，单卡 batch 被卡死</td></tr>\n<tr><td>纯 FP8 注意力与 GEMM</td><td>权重与激活格式</td><td>权重减半，融合简单</td><td>显存红利只有一半</td><td>显存尚有余量、激活侧带宽为主约束</td></tr>\n<tr><td>MX 混合精度分块</td><td>块级缩放格式</td><td>缩放粒度细，回退面积可能更小</td><td>打包与反量化开销高，依赖算子支持</td><td>tcgen05 混合通路支持不完整时的替代</td></tr>\n<tr><td>分块 PTQ 校准</td><td>校准方法论</td><td>给出敏感度排序与回退名单</td><td>32–64 步离线前向</td><td>作为 NVFP4 的上游，不单独部署</td></tr>\n<tr><td>少步/直线采样器</td><td>采样步数</td><td>砍 $N_{\\text{step}}$</td><td>高噪步占比上升，回退不可压缩</td><td>与 NVFP4 正交叠加</td></tr>\n<tr><td>CFG 批合并</td><td>批结构</td><td>等效 batch 翻倍</td><td>显存占用翻倍</td><td>依赖 NVFP4 腾出的显存空间</td></tr>\n<tr><td>特征缓存与块级跳步</td><td>执行 block 数</td><td>减少实际前向</td><td>跳过 block 的量化收益归零</td><td>回退层与常跳 block 重合时协同最佳</td></tr>\n</tbody></table>\n<p>落到工程判断上，决策顺序应是：先测单图 1024² 采样时 batch 是否被显存卡死——若是，NVFP4 混合精度是首选，并用分块 PTQ 校准的输出定回退名单；再测激活在线量化的 amax kernel 是否已与 attention 融合——若未融合且时延收益被吃掉 5–10%，先做 kernel 融合再谈扩大回退面积；最后检查回退比例 $r$ 是否已使 $\\text{Mem}_{W}$ 逼近 FP8 水平——若是，说明量化层选得过多，应缩回退面积或退回纯 FP8，而不是继续堆叠格式。这条判断链把“选哪个算法”变成“先修哪个瓶颈”，避免在同族算法间反复换格式却拿不到净收益。</p>\n\n<h3 id=\"alg-nvfp4-dit-hybrid-sec-52\">五十二 · 与同族算法对照时的选型边界</h3>\n<p>把本方案放进同族候选里比较，先要认清它只动数值格式与算子通路，采样步数与调度原封不动——因此它不是步数蒸馏或 CFG 批合并的替代品，而是可与二者叠加的底层加速层。对照纯 FP8 量化，NVFP4 两级缩放把 per-group 误差压到 FP8 同级，代价是权重打包粒度细到 16 元素一组，并额外携带 FP8 per-group scale 与 FP32 二级 scale，scale overhead 直接进入显存账本：<span class=\"formula\">$$\\text{Mem}_{\\text{DiT}}\\approx\\frac{1}{4}W_{\\text{BF16}}+\\frac{1}{8}A_{\\text{FP8}}+\\text{scale overhead}$$</span>。选型判断应落在“显存带宽是否是当前瓶颈”上：若单张 B200 跑 1024² 采样时 batch 已被权重显存卡死，1/4 权重占用换来 2–3 倍 batch 提升，收益明确；若瓶颈在 attention 或调度开销，量化只带来有限的带宽红利。</p>\n<p>失效条件集中在两处。其一是敏感层回退比例：首末 block 与 adaLN 调制投影若不回退到 FP8/BF16，两级缩放误差会在高噪步被放大，表现为色彩偏移与结构崩坏；回退比例需逐模型校准，且随模型增大而上升，回退过多会反向侵蚀显存收益，规模上限因此受校准集覆盖度约束。其二是激活在线量化的 amax 统计：它引入额外 kernel，若与 attention 融合不好会吃掉 5–10% 时延收益，抵消部分带宽红利。VAE 解码前未把 latent 还原为 BF16 时，解码器数值漂移导致细节糊化，量化收益被画质退化抵消。</p>\n<table class=\"mini\"><thead><tr><th>候选方案</th><th>适用条件</th><th>主要代价</th></tr></thead><tbody><tr><td>纯 FP8 权重×激活</td><td>显存压力中等、敏感层多</td><td>权重仅降至 1/2，batch 提升有限</td></tr><tr><td>本方案 NVFP4×FP8</td><td>1024² 大分辨率、带宽受限、吞吐优先</td><td>回退层与 amax kernel，5–10% 时延风险</td></tr><tr><td>步数蒸馏/CFG 合并</td><td>步数冗余明显</td><td>不改数值精度，与本方案可叠加</td></tr></tbody></table>\n<p>工程判断上，先跑 32–64 步校准前向拿到 per-group amax 与敏感度分数，再决定回退名单：若回退层占比低、amax kernel 能与 attention 融合，则本方案是首选；若校准集覆盖不足或融合质量差，退回纯 FP8 更稳。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · 少步采样与一致性蒸馏</td></tr><tr><td>解决什么</td><td>DiT 主干权重与激活在 Blackwell 上仍以 BF16/FP8 存储，显存带宽与 Tensor Core 利用…</td></tr><tr><td>一句话机制</td><td>对线性层权重做 NVFP4（E2M1 + 两级微缩放）块量化，对激活保留 FP8 或 BF16，敏感层（首末 bloc…</td></tr><tr><td>代价与失效</td><td>首末 block 与调制层必须回退，否则色彩偏移与结构崩坏明显，回退比例需逐模型校准；激活在线量化的 amax 统计引入额外 kernel…</td></tr><tr><td>后继</td><td>DiT 分块 PTQ 校准</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-nvfp4-dit-hybrid · 共 8 个片段</p>\n";break;}}})();
